const CRITICAL_DAMAGE_MULTIPLIER = 1.75;

const charmRankMeta = {
  C: { icon: "◇", label: "Common" },
  B: { icon: "◆", label: "Uncommon" },
  A: { icon: "✦", label: "Rare" },
  S: { icon: "✧", label: "Epic" },
  SS: { icon: "✺", label: "Legendary" }
};

function makeCharm(id, name, rank, type, effectType, value, description, extra = {}) {
  return {
    id,
    name,
    rank,
    type,
    effectType,
    value,
    description,
    effect: description,
    icon: extra.icon || charmRankMeta[rank].icon,
    ...extra
  };
}

