const tutorialSlides = [
  {
    title: "ระบบสมัครสมาชิก เก็บคะแนน และติดตามคะแนน",
    description: "อธิบายการเข้าสู่ระบบ การสะสม Grammaria และการติดตามความก้าวหน้าจากหน้าเมนู",
    image: "assets/tutorial/tutorial_01_account_score_menu.png"
  },
  {
    title: "หน้า Lesson",
    description: "อธิบายการอ่านบทเรียน การกดถัดไป ย้อนกลับ ดูคำอธิบาย และทบทวนเนื้อหา",
    image: "assets/tutorial/tutorial_02_lesson.png"
  },
  {
    title: "หน้าต่อสู้",
    description: "อธิบายข้อมูลบอส ผู้เล่น เทิร์น คำถาม สกิล ชาม Grammaria และการป้องกัน",
    image: "assets/tutorial/tutorial_03_battle.png"
  }
];

let currentTutorialSlideIndex = 0;

function getTutorialSlide(index = currentTutorialSlideIndex) {
  return tutorialSlides[index] || tutorialSlides[0] || {
    title: "วิธีเล่น Lingua",
    description: "คู่มือการใช้งานเกมสำหรับนักเรียน",
    image: ""
  };
}

function renderTutorialSlide() {
  const slideCount = tutorialSlides.length;
  const maxIndex = Math.max(0, slideCount - 1);
  currentTutorialSlideIndex = Math.min(Math.max(0, currentTutorialSlideIndex), maxIndex);
  const slide = getTutorialSlide();
  const readableIndex = slideCount ? currentTutorialSlideIndex + 1 : 0;

  if (els.tutorialGuideTitle) {
    els.tutorialGuideTitle.textContent = slide.title || "วิธีเล่น Lingua";
  }
  if (els.tutorialGuideDescription) {
    els.tutorialGuideDescription.textContent = slide.description || "";
  }
  if (els.tutorialGuideCounter) {
    els.tutorialGuideCounter.textContent = `${readableIndex} / ${slideCount}`;
  }

  const hasImage = Boolean(slide.image);
  if (els.tutorialGuidePlaceholder) {
    els.tutorialGuidePlaceholder.classList.toggle("hidden", hasImage);
  }
  if (els.tutorialGuideImage) {
    els.tutorialGuideImage.onload = () => {
      els.tutorialGuideImage.classList.remove("hidden");
      els.tutorialGuidePlaceholder?.classList.add("hidden");
    };
    els.tutorialGuideImage.onerror = () => {
      els.tutorialGuideImage.classList.add("hidden");
      els.tutorialGuidePlaceholder?.classList.remove("hidden");
    };
    els.tutorialGuideImage.alt = `คู่มือวิธีเล่น Lingua: ${slide.title || "วิธีเล่น"}`;
    els.tutorialGuideImage.classList.toggle("hidden", !hasImage);
    els.tutorialGuideImage.src = hasImage ? slide.image : "";
  }

  setButtonEnabled(els.tutorialPreviousButton, currentTutorialSlideIndex > 0);
  setButtonEnabled(els.tutorialNextButton, currentTutorialSlideIndex < maxIndex);
}

function openTutorialGuide(startSlideIndex = 0) {
  currentTutorialSlideIndex = Math.max(0, Number(startSlideIndex) || 0);
  renderTutorialSlide();
  showScene("tutorialGuide");
}

function nextTutorialSlide() {
  if (currentTutorialSlideIndex >= tutorialSlides.length - 1) {
    return;
  }
  currentTutorialSlideIndex += 1;
  renderTutorialSlide();
  saveLastSceneForCurrentUser("tutorialGuide", { tutorialSlideIndex: currentTutorialSlideIndex });
}

function previousTutorialSlide() {
  if (currentTutorialSlideIndex <= 0) {
    return;
  }
  currentTutorialSlideIndex -= 1;
  renderTutorialSlide();
  saveLastSceneForCurrentUser("tutorialGuide", { tutorialSlideIndex: currentTutorialSlideIndex });
}

function returnToMainMenuFromTutorial() {
  renderMainMenu();
  showScene("mainMenu");
}

function openCreatorCredits() {
  showScene("creatorCredits");
}

function returnToMainMenuFromCreatorCredits() {
  renderMainMenu();
  showScene("mainMenu");
}

function updateDeveloperCreditVisibility(sceneName) {
  const credit = document.getElementById("developerCredit");
  if (!credit) {
    return;
  }
  credit.classList.toggle("is-hidden", ["story", "battle", "creatorCredits", "pvp", "verbMemoryPractice"].includes(sceneName));
}

function showScene(name) {
  cleanupButtonsForSceneChange(name);
  if (name !== "battle") {
    cleanupBattleSkillEffects();
  }
  if (name === "login" || name === "createCharacter") {
    stopTypewriter();
    state.isTypingDialogue = false;
  }
  if (name !== "story") {
    stopDialogueTypeSfx();
  }
  Object.values(scenes).forEach(scene => scene.classList.remove("active"));
  if (["story", "battle", "mainMenu"].includes(name)) {
    refreshPlayerCharacterSprites();
  }
  scenes[name].classList.add("active");
  updateDeveloperCreditVisibility(name);
  applyDebugButtonVisibility();
  updateManualSaveButtonVisibility(name);
  playBgmForScene(name);
  renderBattleTurnIndicator();
  saveLastSceneForCurrentUser(name);
}

function cleanupButtonsForSceneChange(nextScene) {
  if (nextScene !== "battle") {
    clearParryLayoutState();
  }
  if (nextScene !== "battle") {
    cleanupBattleInputState();
  }
  if (nextScene !== "story" && nextScene !== "battle") {
    clearBattleButtonAction({ hide: true });
  }
}

function bgmKeyForScene(sceneName) {
  if (sceneName === "login" || sceneName === "mainMenu" || sceneName === "createCharacter") {
    return "login";
  }
  if (shouldUseLinguaBreakerBgm(sceneName)) {
    return "linguaBreaker";
  }
  if (shouldUseEdForgeBgm(sceneName)) {
    return "edForge";
  }
  if (sceneName === "battle") {
    return "battle";
  }
  return "hall";
}

function shouldUseLinguaBreakerBgm(sceneName) {
  if (["pvp", "vsBosses", "verbMemoryPractice"].includes(sceneName)) {
    return true;
  }
  return sceneName === "battle" && Boolean(state.vsBossPractice?.active);
}

function getBgmContextStages(sceneName) {
  const stages = sceneName === "battle"
    ? [state.actBattle?.stage]
    : [
      state.currentLessonStage,
      state.postBossDialogueStage
    ];
  if (typeof getPlayableStages === "function") {
    stages.push(getPlayableStages()[state.actStageIndex]);
  }
  return stages.filter(Boolean);
}

function isEdForgeBgmStage(stage) {
  const stageId = typeof stage === "string" ? stage : stage?.id;
  return ED_FORGE_BGM_STAGE_IDS.has(stageId);
}

function shouldUseEdForgeBgm(sceneName) {
  if (sceneName !== "story" && sceneName !== "battle") {
    return false;
  }
  return getBgmContextStages(sceneName).some(isEdForgeBgmStage);
}

function playBgmForScene(sceneName) {
  if (sceneName === "victory") {
    playVictorySceneMusicOnce();
    return;
  }
  stopVictorySceneMusic();
  playBgm(bgmKeyForScene(sceneName));
}

function playBgm(key, options = {}) {
  if (!bgmTracks[key]) {
    return false;
  }
  if (state.isMuted) {
    return false;
  }
  if (!state.audioUnlocked) {
    state.pendingBgmKey = key;
    return false;
  }

  const shouldRestart = options.restart === true;
  if (!shouldRestart && state.currentBgmKey === key && !bgmTracks[key].paused) {
    if (state.pendingBgmKey === key) {
      state.pendingBgmKey = "";
    }
    return true;
  }

  const previousKey = state.currentBgmKey;
  const previousTrack = previousKey ? bgmTracks[previousKey] : null;
  const shouldFadeEdForgeTransition = previousKey &&
    previousKey !== key &&
    (previousKey === "edForge" || key === "edForge") &&
    options.fade !== false;

  Object.entries(bgmTracks).forEach(([trackKey, track]) => {
    if (trackKey !== key && (!shouldFadeEdForgeTransition || trackKey !== previousKey)) {
      clearBgmFadeTimer(trackKey);
      track.pause();
      track.currentTime = 0;
    }
  });

  state.currentBgmKey = key;
  bgmTracks[key].loop = Boolean(BGM_LOOP[key]);
  bgmTracks[key].muted = state.isMuted;
  if (shouldRestart) {
    bgmTracks[key].currentTime = 0;
  }
  if (shouldFadeEdForgeTransition) {
    fadeOutPreviousBgm(previousKey, previousTrack);
    fadeInBgm(key, bgmTracks[key]);
  } else {
    clearBgmFadeTimer(key);
    bgmTracks[key].volume = getBgmVolume(key);
  }
  const playPromise = bgmTracks[key].play();
  if (playPromise && typeof playPromise.then === "function") {
    playPromise
      .then(() => {
        if (state.pendingBgmKey === key) {
          state.pendingBgmKey = "";
        }
      })
      .catch(error => {
        state.pendingBgmKey = key;
        console.warn("[BGM] Playback blocked until user interaction", {
          trackId: key,
          src: BGM_PATHS[key],
          currentTrackId: state.currentBgmKey,
          error
        });
      });
  }
  return true;
}

function clearBgmFadeTimer(key) {
  const frameId = bgmFadeTimers.get(key);
  if (frameId) {
    cancelAnimationFrame(frameId);
    bgmFadeTimers.delete(key);
  }
}

function fadeBgmTrack(key, track, fromVolume, toVolume, durationMs, onComplete) {
  clearBgmFadeTimer(key);
  const startedAt = performance.now();
  track.volume = fromVolume;

  const step = now => {
    const progress = clamp((now - startedAt) / durationMs, 0, 1);
    track.volume = fromVolume + (toVolume - fromVolume) * progress;
    if (progress >= 1) {
      bgmFadeTimers.delete(key);
      if (onComplete) {
        onComplete();
      }
      return;
    }
    bgmFadeTimers.set(key, requestAnimationFrame(step));
  };

  bgmFadeTimers.set(key, requestAnimationFrame(step));
}

function fadeOutPreviousBgm(previousKey, previousTrack) {
  if (!previousTrack || previousTrack.paused) {
    return;
  }
  fadeBgmTrack(previousKey, previousTrack, previousTrack.volume, 0, BGM_FADE_MS, () => {
    previousTrack.pause();
    previousTrack.currentTime = 0;
    previousTrack.volume = getBgmVolume(previousKey);
  });
}

function fadeInBgm(key, track) {
  clearBgmFadeTimer(key);
  const targetVolume = getBgmVolume(key);
  track.volume = 0;
  fadeBgmTrack(key, track, 0, targetVolume, BGM_FADE_MS);
}

function playVictorySceneMusic() {
  const didPlay = playBgm("victoryScene", { restart: true });
  if (didPlay) {
    state.victoryMusicActive = true;
  }
  return didPlay;
}

function playVictorySceneMusicOnce() {
  if (state.victoryMusicPlayedForBattle) {
    return false;
  }

  const didPlay = playVictorySceneMusic();
  if (didPlay) {
    state.victoryMusicPlayedForBattle = true;
  }
  return didPlay;
}

function stopVictorySceneMusic() {
  const track = bgmTracks.victoryScene;
  if (!track) {
    return;
  }
  track.pause();
  track.currentTime = 0;
  state.victoryMusicActive = false;
  if (state.currentBgmKey === "victoryScene") {
    state.currentBgmKey = "";
  }
}

function resetVictorySceneMusicForBattle() {
  state.victoryMusicPlayedForBattle = false;
  stopVictorySceneMusic();
}

function shouldPlayDialogueTypeSfx() {
  if (!canPlayTypewriterSfx()) {
    return false;
  }
  return state.isTypingDialogue
    && state.audioUnlocked
    && state.typewriterAudioUnlocked
    && !state.isMuted
    && scenes.story
    && scenes.story.classList.contains("active")
    && els.dialoguePanel
    && !els.dialoguePanel.classList.contains("hidden");
}

function canPlayTypewriterSfx() {
  if (state.isPrologueActive) {
    return state.prologueTyping === true;
  }
  return state.isTypingDialogue
    && scenes.story
    && scenes.story.classList.contains("active")
    && els.dialoguePanel
    && !els.dialoguePanel.classList.contains("hidden");
}

function prepareDialogueTypeSfxTrack(track, volume = DIALOGUE_TYPE_SFX_VOLUME) {
  track.preload = "auto";
  track.src = DIALOGUE_TYPE_SFX_PATH;
  track.volume = volume;
  track.muted = state.isMuted;
  try {
    track.load();
  } catch (error) {
    console.warn("[Audio] typewriter file failed to load", error);
  }
}

function resumeAudioContextIfPresent() {
  const context = window.audioContext || window.gameAudioContext || window.linguaAudioContext;
  if (!context || context.state !== "suspended" || typeof context.resume !== "function") {
    return;
  }

  context.resume().catch(error => {
    console.warn("[Audio] audio context resume failed", error);
  });
}

function seekDialogueTypeSfxStart(track) {
  try {
    track.currentTime = Math.min(DIALOGUE_TYPE_SFX_OFFSET, Math.max(track.duration - 0.05, 0) || DIALOGUE_TYPE_SFX_OFFSET);
  } catch (error) {
    track.currentTime = 0;
  }
}

function getDialogueTypeSfxTrack() {
  const track = dialogueTypeSfxPool[state.dialogueTypeSfxPoolIndex % dialogueTypeSfxPool.length];
  state.dialogueTypeSfxPoolIndex += 1;
  return track;
}

function prepareSfxTrack(track, key) {
  track.preload = "auto";
  track.volume = SFX_VOLUME[key] || 0.5;
  track.muted = state.isMuted;
  try {
    track.load();
  } catch (error) {
    console.warn(`[Audio] ${key} SFX failed to load`, error);
  }
}

function getSfxTrack(key) {
  const pool = sfxPools[key];
  if (!pool || !pool.length) {
    return null;
  }
  const index = sfxPoolIndexes[key] % pool.length;
  sfxPoolIndexes[key] = index + 1;
  return pool[index];
}

function playSfx(key) {
  if (!state.audioUnlocked || state.isMuted) {
    return;
  }

  const track = getSfxTrack(key);
  if (!track) {
    return;
  }

  track.pause();
  track.currentTime = 0;
  track.volume = SFX_VOLUME[key] || 0.5;
  track.muted = state.isMuted;
  track.play().catch(() => {});
}

function playAttackSfx() {
  playSfx("attack");
}

function playButtonSfx() {
  if (!state.audioUnlocked) {
    unlockGameAudio();
  }
  playSfx("button");
}

function shouldPlayButtonSfxForEvent(event) {
  const button = event.target?.closest?.("button");
  if (!button || button.disabled || button.getAttribute("aria-disabled") === "true") {
    return false;
  }
  if (button.id === "stopChargeButton") {
    return false;
  }
  return true;
}

function handleButtonSfxPointer(event) {
  if (shouldPlayButtonSfxForEvent(event)) {
    playButtonSfx();
  }
}

function handleButtonSfxKey(event) {
  if (event.repeat || (event.key !== "Enter" && event.key !== " ")) {
    return;
  }
  if (shouldPlayButtonSfxForEvent(event)) {
    playButtonSfx();
  }
}

function playDialogueTypeSfxTick(character) {
  if (!shouldPlayDialogueTypeSfx() || /\s/.test(character)) {
    return;
  }

  const now = typeof performance !== "undefined" ? performance.now() : Date.now();
  if (state.typewriterIndex % 2 !== 0 || now - state.lastDialogueTypeSfxAt < DIALOGUE_TYPE_SFX_COOLDOWN_MS) {
    return;
  }
  state.lastDialogueTypeSfxAt = now;

  const track = getDialogueTypeSfxTrack();
  if (track.dialogueTypeSfxStopTimer) {
    clearTimeout(track.dialogueTypeSfxStopTimer);
  }

  track.pause();
  seekDialogueTypeSfxStart(track);
  track.volume = DIALOGUE_TYPE_SFX_VOLUME;
  track.muted = state.isMuted;
  track.play().catch(error => {
    if (!state.dialogueTypeSfxWarned) {
      console.warn("[Audio] typewriter play failed", error);
      state.dialogueTypeSfxWarned = true;
    }
  });

  track.dialogueTypeSfxStopTimer = setTimeout(() => {
    track.pause();
    track.currentTime = 0;
    track.dialogueTypeSfxStopTimer = null;
  }, DIALOGUE_TYPE_SFX_TICK_MS);
}

function stopDialogueTypeSfx() {
  [dialogueTypeSfx, ...dialogueTypeSfxPool].forEach(track => {
    if (track.dialogueTypeSfxStopTimer) {
      clearTimeout(track.dialogueTypeSfxStopTimer);
      track.dialogueTypeSfxStopTimer = null;
    }
    track.pause();
    track.currentTime = 0;
  });
}

function stopPrologueTypewriterSound() {
  dialogueTypeSfxPool.forEach(track => {
    if (track.dialogueTypeSfxStopTimer) {
      clearTimeout(track.dialogueTypeSfxStopTimer);
      track.dialogueTypeSfxStopTimer = null;
    }
    track.pause();
    track.currentTime = 0;
  });
  state.lastDialogueTypeSfxAt = 0;
}

function clearPrologueTypingTimer() {
  if (state.prologueTimer) {
    clearTimeout(state.prologueTimer);
    state.prologueTimer = null;
  }
}

function unlockGameAudio() {
  const shouldLogUnlock = !state.audioUnlocked || !state.typewriterAudioUnlocked || Boolean(state.pendingBgmKey);
  if (shouldLogUnlock) {
    console.log("[Audio] unlock requested");
  }
  resumeAudioContextIfPresent();
  if (!state.audioUnlocked) {
    state.audioUnlocked = true;
    state.audioLocked = false;
  }

  const activeScene = Object.keys(scenes).find(key => scenes[key].classList.contains("active")) || "login";
  if (state.pendingBgmKey && bgmTracks[state.pendingBgmKey]) {
    playBgm(state.pendingBgmKey, { fade: false });
  } else {
    playBgmForScene(activeScene);
  }

  if (state.typewriterAudioUnlocked) {
    return;
  }

  [dialogueTypeSfx, ...dialogueTypeSfxPool].forEach(track => prepareDialogueTypeSfxTrack(track, DIALOGUE_TYPE_SFX_VOLUME));
  Object.entries(sfxPools).forEach(([key, pool]) => {
    pool.forEach(track => prepareSfxTrack(track, key));
  });
  state.typewriterAudioUnlocked = true;
  state.audioLocked = false;
}

function toggleMute() {
  state.isMuted = !state.isMuted;
  Object.values(bgmTracks).forEach(track => {
    track.muted = state.isMuted;
    if (state.isMuted) {
      track.pause();
    }
  });
  [dialogueTypeSfx, ...dialogueTypeSfxPool].forEach(track => {
    track.muted = state.isMuted;
  });
  Object.values(sfxPools).flat().forEach(track => {
    track.muted = state.isMuted;
  });

  if (state.isMuted) {
    stopDialogueTypeSfx();
  }

  if (els.muteButton) {
    els.muteButton.textContent = state.isMuted ? "เสียง: ปิด" : "เสียง: เปิด";
    els.muteButton.setAttribute("aria-pressed", state.isMuted ? "true" : "false");
  }

  if (!state.isMuted) {
    unlockGameAudio();
    if (state.victoryMusicActive || state.currentBgmKey === "victoryScene") {
      playBgm("victoryScene");
    } else {
      const activeScene = Object.keys(scenes).find(key => scenes[key].classList.contains("active")) || "login";
      playBgmForScene(activeScene);
    }
  }
}

function runSceneTransition(message, onCovered) {
  if (state.isTransitioning) {
    return;
  }

  state.isTransitioning = true;
  els.transitionText.textContent = message;
  els.sceneTransition.classList.remove("hidden");

  requestAnimationFrame(() => {
    els.sceneTransition.classList.add("visible");
  });

  setTimeout(() => {
    onCovered();

    setTimeout(() => {
      els.sceneTransition.classList.remove("visible");

      setTimeout(() => {
        els.sceneTransition.classList.add("hidden");
        state.isTransitioning = false;
        updateManualSaveButtonVisibility();
      }, 620);
    }, 160);
  }, 620);
}

function resetSceneTransitionOverlay() {
  if (els.sceneTransition) {
    els.sceneTransition.classList.remove("visible");
    els.sceneTransition.classList.add("hidden");
  }
  state.isTransitioning = false;
  updateManualSaveButtonVisibility();
}

function runLessonUnitTransition(message, { onCovered, onFinished } = {}) {
  if (state.isTransitioning) {
    return false;
  }

  state.isTransitioning = true;
  setButtonEnabled(els.nextDialogueButton, false);
  setButtonEnabled(els.battleButton, false);
  setButtonEnabled(els.continueBattleButton, false);
  if (els.transitionText) {
    els.transitionText.textContent = message || "กำลังเดินทางสู่บทเรียนถัดไป...";
  }
  els.sceneTransition.classList.remove("hidden");

  requestAnimationFrame(() => {
    els.sceneTransition.classList.add("visible");
  });

  setTimeout(() => {
    try {
      if (typeof onCovered === "function") {
        onCovered();
      }
    } catch (error) {
      console.error("[LessonTransition] Failed while scene was covered", error);
      resetSceneTransitionOverlay();
      return;
    }

    setTimeout(() => {
      els.sceneTransition.classList.remove("visible");

      setTimeout(() => {
        resetSceneTransitionOverlay();
        try {
          if (typeof onFinished === "function") {
            onFinished();
          }
        } catch (error) {
          console.error("[LessonTransition] Failed after fade in", error);
          resetSceneTransitionOverlay();
        }
      }, 620);
    }, 160);
  }, 620);

  return true;
}

function closeGameModal() {
  if (!els.gameModal) {
    return;
  }

  els.gameModal.dataset.modalLocked = "false";
  els.gameModal.classList.add("hidden");
  els.gameModalClose.classList.remove("hidden");
  setButtonEnabled(els.gameModalClose, true);
  els.gameModalTitle.textContent = "";
  els.gameModalBody.textContent = "";
  els.gameModalContent.innerHTML = "";
  els.gameModalActions.innerHTML = "";
}

function isGameModalOpen() {
  return els.gameModal && !els.gameModal.classList.contains("hidden");
}

function setButtonEnabled(button, enabled) {
  if (!button) {
    return;
  }

  button.disabled = !enabled;
  button.setAttribute("aria-disabled", enabled ? "false" : "true");
  button.classList.toggle("disabled", !enabled);
  button.classList.toggle("is-disabled", !enabled);
  if (enabled) {
    button.classList.remove("is-locked");
    delete button.dataset.buttonLocked;
  }
}

function clearButtonAction(button, options = {}) {
  if (!button) {
    return;
  }

  button.onclick = null;
  delete button.dataset.buttonLocked;
  button.classList.remove("is-locked", "is-loading");
  if (options.disable !== false) {
    setButtonEnabled(button, false);
  }
}

function setButtonAction(button, label, handler, options = {}) {
  if (!button) {
    return;
  }

  clearButtonAction(button, { disable: false });
  if (label !== null && label !== undefined) {
    button.textContent = label;
  }
  if (options.hidden === false) {
    button.classList.remove("hidden");
  } else if (options.hidden === true) {
    button.classList.add("hidden");
  }
  setButtonEnabled(button, options.enabled !== false);

  button.onclick = event => {
    if (event) {
      event.preventDefault();
      event.stopPropagation();
    }
    if (button.disabled || button.classList.contains("hidden")) {
      return;
    }
    if (state.isTransitioning && !options.allowDuringTransition) {
      return;
    }
    if (options.lock !== false) {
      if (button.dataset.buttonLocked === "true") {
        return;
      }
      button.dataset.buttonLocked = "true";
      button.classList.add("is-locked");
      setButtonEnabled(button, false);
    }
    if (typeof handler === "function") {
      const result = handler(event);
      if (result === false && options.lock !== false) {
        delete button.dataset.buttonLocked;
        button.classList.remove("is-locked");
        setButtonEnabled(button, true);
      }
    }
  };
}

function runButtonActionOnce(button, callback) {
  if (!button || button.disabled || button.dataset.buttonLocked === "true") {
    return false;
  }
  button.dataset.buttonLocked = "true";
  button.classList.add("is-locked");
  setButtonEnabled(button, false);
  if (typeof callback === "function") {
    callback();
  }
  return true;
}

function openGameModal({ title, body = "", content = "", actions = [], lockClose = false }) {
  if (!els.gameModal) {
    return;
  }

  els.gameModal.dataset.modalLocked = "false";
  els.gameModalClose.classList.toggle("hidden", Boolean(lockClose));
  setButtonEnabled(els.gameModalClose, !lockClose);
  els.gameModalTitle.textContent = title;
  els.gameModalBody.textContent = body;
  els.gameModalContent.innerHTML = "";
  els.gameModalActions.innerHTML = "";

  if (typeof content === "string") {
    els.gameModalContent.innerHTML = content;
  } else if (content) {
    els.gameModalContent.appendChild(content);
  }

  actions.forEach(action => {
    const button = document.createElement("button");
    button.type = "button";
    button.className = action.primary ? "primary-button" : "secondary-button";
    button.textContent = action.label;
    button.addEventListener("click", event => {
      event.preventDefault();
      event.stopPropagation();
      if (els.gameModal.dataset.modalLocked === "true") {
        return;
      }
      els.gameModal.dataset.modalLocked = "true";
      els.gameModalActions.querySelectorAll("button").forEach(actionButton => setButtonEnabled(actionButton, false));
      setButtonEnabled(els.gameModalClose, false);
      if (typeof action.onClick === "function") {
        action.onClick(event);
      }
    });
    els.gameModalActions.appendChild(button);
  });

  els.gameModal.classList.remove("hidden");
}

function showOnlyBattlePanel(panelToShow) {
  els.questionPanel?.classList.remove("boss-v2-arrangement-active");
  scenes.battle?.classList.remove("arrangement-layout-active");
  [
    els.bossIntentPanel,
    els.actionMenu,
    els.itemPanel,
    els.questionPanel,
    els.charmPanel,
    els.chargePanel,
    els.parryPanel,
    els.pointParryPanel,
    els.continueBattleButton
  ]
    .filter(Boolean)
    .forEach(panel => panel.classList.add("hidden"));

  if (panelToShow !== els.continueBattleButton) {
    clearButtonAction(els.continueBattleButton, { disable: true });
  }
  if (panelToShow !== els.bossIntentPanel) {
    clearButtonAction(els.bossIntentReadyButton, { disable: true });
  }

  if (panelToShow) {
    panelToShow.classList.remove("hidden");
  }
  updateParryLayoutState(panelToShow);
}

function isParryLayoutPanel(panel) {
  return panel === els.parryPanel || panel === els.pointParryPanel;
}

function syncVisibleViewportHeight() {
  const height = window.visualViewport?.height || window.innerHeight;
  if (!height) {
    return;
  }
  document.documentElement.style.setProperty("--visible-viewport-height", `${Math.round(height)}px`);
}

function updateParryLayoutState(panelToShow = null) {
  syncVisibleViewportHeight();
  const isActive = isParryLayoutPanel(panelToShow);
  document.body.classList.toggle("parry-active", isActive);
  if (scenes.battle) {
    scenes.battle.classList.toggle("parry-layout-active", isActive);
  }
}

function clearParryLayoutState() {
  document.body.classList.remove("parry-active");
  if (scenes.battle) {
    scenes.battle.classList.remove("parry-layout-active");
  }
}

function startParryBarAfterLayout(challengeId, durationMs, onTimeout) {
  syncVisibleViewportHeight();
  requestAnimationFrame(() => {
    requestAnimationFrame(() => {
      if (!isCurrentParryBarChallenge(challengeId)) {
        return;
      }
      scheduleParryBarArming(challengeId);
      startParryGauge(challengeId);
      state.parry.resolveTimeout = setTimeout(() => {
        if (!isCurrentParryBarChallenge(challengeId)) {
          return;
        }
        onTimeout();
      }, durationMs);
    });
  });
}

function enableBattleButton(button) {
  setButtonEnabled(button, true);
}

function disableBattleButton(button) {
  setButtonEnabled(button, false);
}

function resetBattleContinueControls() {
  clearButtonAction(els.continueBattleButton, { disable: false });
  clearButtonAction(els.bossIntentReadyButton, { disable: false });
}

function showBattleContinueButton(label, onClick) {
  setButtonAction(els.continueBattleButton, label, onClick, { hidden: false });
}

function setBattleButtonAction(label, onClick, options = {}) {
  setButtonAction(els.battleButton, label, onClick, { hidden: false, ...options });
}

function clearBattleButtonAction({ hide = true } = {}) {
  clearButtonAction(els.battleButton, { disable: true });
  if (hide && els.battleButton) {
    els.battleButton.classList.add("hidden");
  }
}

function setBattleTurnOwner(owner) {
  const battle = state.actBattle;
  if (battle && (owner === "player" || owner === "enemy")) {
    battle.currentTurnActor = owner === "enemy" ? "boss" : "player";
  }
  els.battlePlayer.classList.toggle("is-active-turn", owner === "player");
  els.battleEnemy.classList.toggle("is-active-turn", owner === "enemy");
  renderBattleTurnIndicator();
}

function getBattleCurrentActorForDisplay(battle = state.actBattle) {
  if (!battle || isActBattleEnded(battle)) {
    return "";
  }
  return battle.currentTurnActor || (
    battle.pendingBossTurn ||
    battle.pendingBossAction ||
    battle.awaitingParry ||
    battle.awaitingPrepare ||
    battle.heavyAttackState?.active ||
    battle.bossGrammarChallenge?.active
      ? "boss"
      : "player"
  );
}

function getBattleActorLabel(actor, { current = false } = {}) {
  if (actor === "boss") {
    return current ? "ตาของบอส" : "บอส";
  }
  return current ? "ตาของผู้เล่น" : "ผู้เล่น";
}

function buildAlternatingTurnPreview(currentActor, count = 5) {
  const preview = [];
  let actor = currentActor === "boss" ? "player" : "boss";
  for (let index = 0; index < count; index += 1) {
    preview.push({
      actor,
      label: getBattleActorLabel(actor)
    });
    actor = actor === "boss" ? "player" : "boss";
  }
  return preview;
}

function getBattleTurnPreview(count = 5) {
  const battle = state.actBattle;
  const currentActor = getBattleCurrentActorForDisplay(battle);
  if (!currentActor) {
    return [];
  }
  return buildAlternatingTurnPreview(currentActor, count).slice(0, count);
}

function hideBattleTurnIndicator() {
  if (!els.battleTurnIndicator) {
    return;
  }
  els.battleTurnIndicator.classList.add("hidden");
  if (els.battleUpcomingTurnList) {
    els.battleUpcomingTurnList.innerHTML = "";
  }
}

function renderBattleTurnIndicator() {
  if (!els.battleTurnIndicator || !els.battleCurrentTurnActor || !els.battleUpcomingTurnList) {
    return;
  }

  const battle = state.actBattle;
  const isBattleSceneActive = scenes.battle?.classList.contains("active");
  const currentActor = getBattleCurrentActorForDisplay(battle);
  if (!isBattleSceneActive || !currentActor) {
    hideBattleTurnIndicator();
    return;
  }

  const upcomingTurns = getBattleTurnPreview(5);
  if (upcomingTurns.length !== 5) {
    hideBattleTurnIndicator();
    return;
  }

  els.battleTurnIndicator.classList.remove("hidden", "is-player-turn", "is-boss-turn");
  els.battleTurnIndicator.classList.add(currentActor === "boss" ? "is-boss-turn" : "is-player-turn");
  els.battleCurrentTurnActor.textContent = getBattleActorLabel(currentActor, { current: true });
  els.battleCurrentTurn.dataset.actor = currentActor;
  els.battleUpcomingTurnList.innerHTML = "";
  upcomingTurns.forEach((turn, index) => {
    const slot = document.createElement("div");
    slot.className = `battle-turn-slot battle-turn-slot--${turn.actor}`;
    slot.innerHTML = `
      <span class="turn-order-number">${index + 1}</span>
      <span class="turn-actor-name">${turn.label}</span>
    `;
    els.battleUpcomingTurnList.appendChild(slot);
  });
}

function setActionButtonsEnabled(isEnabled) {
  [els.attackButton, els.itemButton, els.focusButton].forEach(button => {
    setButtonEnabled(button, isEnabled);
  });
  updateActActionMenuState();
}

function isActBattleEnded(battle = state.actBattle) {
  return !battle || battle.victoryHandled || battle.isDefeated || battle.battleLocked || battle.phase === "ended" || battle.isActive === false;
}

function disableBattleInputsForDefeat() {
  setActionButtonsEnabled(false);
  [
    els.answerOptions,
    els.charmOptions,
    els.continueBattleButton,
    els.stopChargeButton,
    els.parryButton,
    els.bossIntentReadyButton
  ].filter(Boolean).forEach(container => {
    if (container.tagName === "BUTTON") {
      disableBattleButton(container);
      return;
    }
    container.querySelectorAll("button").forEach(button => {
      button.disabled = true;
    });
  });
}

function cleanupBattleInputState() {
  stopTimer("charge");
  stopParryCountdown();
  cleanupPointParryRingUI();
  cleanupBossHeavyAttackChain({ clearParryUi: false });
  clearButtonAction(els.continueBattleButton, { disable: true });
  clearButtonAction(els.bossIntentReadyButton, { disable: true });
  setActionButtonsEnabled(false);
  state.parryAttack = null;
  state.shield = 0;
  state.guardShield = 0;
}

function cleanupBossHeavyAttackChain({ clearParryUi = true } = {}) {
  const battle = state.actBattle;
  if (battle) {
    battle.heavyAttackState = null;
  }
  if (clearParryUi) {
    stopParryCountdown();
    cleanupPointParryRingUI();
  }
}

function getRevivedHp(percent = REVIVE_CONFIG.hpPercentAfterRevive) {
  return Math.max(1, Math.round(100 * percent));
}

function tryPlayerRevive(reason = "") {
  const battle = state.actBattle;
  if (!battle || battle.reviveUsedThisBattle || (battle.reviveCount || 0) >= REVIVE_CONFIG.maxRevivesPerBattle) {
    return false;
  }

  const effects = state.battleActiveEffects || {};
  if (effects.surviveFatalOnce) {
    effects.surviveFatalOnce = false;
    battle.reviveUsedThisBattle = true;
    battle.reviveCount = (battle.reviveCount || 0) + 1;
    battle.justRevived = true;
    state.playerHp = getRevivedHp(effects.surviveFatalHealPercent || 0.4);
    updateBattleStats();
    syncBattleStateToPlayerData();
    els.battleMessage.textContent = `${reason ? `${reason}\n` : ""}เครื่องรางแห่ง Lingua เปล่งประกาย! พลังสุดท้ายปกป้องเจ้าจากความพ่ายแพ้`;
    return true;
  }

  if (!REVIVE_CONFIG.enabled || Math.random() > REVIVE_CONFIG.chance) {
    return false;
  }

  battle.reviveUsedThisBattle = true;
  battle.reviveCount = (battle.reviveCount || 0) + 1;
  battle.justRevived = true;
  state.playerHp = getRevivedHp();
  updateBattleStats();
  syncBattleStateToPlayerData();
  els.battleMessage.textContent = `${reason ? `${reason}\n` : ""}แสงเวทของมาสเตอร์เวร์ออนสว่างขึ้น! เจ้าได้รับโอกาสสุดท้ายและฟื้นพลังกลับมา`;
  return true;
}

function resolvePlayerDefeat(reason = "HP เหลือ 0") {
  const battle = state.actBattle;
  if (!battle) {
    if (state.playerHp <= 0) {
      showLegacyDefeatScreen(reason);
      return true;
    }
    return false;
  }
  if (battle.battleLocked || battle.isDefeated || battle.victoryHandled) {
    return true;
  }
  if (state.playerHp > 0) {
    return false;
  }

  state.playerHp = 0;
  updateBattleStats();
  syncBattleStateToPlayerData();

  if (tryPlayerRevive(reason)) {
    return false;
  }

  showDefeatScreen(reason);
  return true;
}

function showLegacyDefeatScreen(reason = "HP เหลือ 0") {
  state.playerHp = 0;
  disableBattleInputsForDefeat();
  cleanupBattleInputState();
  updateBattleStats();

  const content = document.createElement("div");
  content.className = "defeat-result";
  content.innerHTML = `
    <p class="defeat-cause">${reason}</p>
    <p>พลังของเจ้าหมดลงในการต่อสู้ครั้งนี้ แต่บทเรียนยังไม่สิ้นสุด</p>
  `;

  openGameModal({
    title: "พ่ายแพ้…",
    body: "HP เหลือ 0",
    content,
    lockClose: true,
    actions: [
      {
        label: "ลองสู้ใหม่",
        primary: true,
        onClick: () => {
          closeGameModal();
          resetBattle();
        }
      },
      {
        label: "ไปเรียนบทนี้ใหม่",
        onClick: () => {
          closeGameModal();
          resetBattle();
          showScene("story");
        }
      }
    ]
  });
}

function showDefeatScreen(reason = "HP เหลือ 0") {
  const battle = state.actBattle;
  if (!battle) {
    return;
  }

  battle.isDefeated = true;
  battle.battleLocked = true;
  battle.isActive = false;
  battle.phase = "defeated";
  disableBattleInputsForDefeat();
  cleanupBattleInputState();
  showOnlyBattlePanel(null);
  updateBattleStats();
  if (isVsBossPracticeActive()) {
    void finishVsBossPracticeBattle({ bossDefeated: false });
    return;
  }
  saveProgress({
    currentStageId: battle.stage.id,
    currentLessonId: battle.stage.id,
    currentScreen: "lesson",
    lastSafeScreen: "lesson",
    currentDialogueIndex: battle.reviewDialogueIndex || 0,
    currentLessonStepIndex: battle.reviewLessonStepIndex || 0
  });

  const content = document.createElement("div");
  content.className = "defeat-result";
  content.innerHTML = `
    <p class="defeat-cause">${reason || "HP เหลือ 0"}</p>
    <p>พลังของเจ้าหมดลงในการต่อสู้ครั้งนี้ แต่บทเรียนยังไม่สิ้นสุด</p>
  `;

  openGameModal({
    title: "พ่ายแพ้…",
    body: "HP เหลือ 0",
    content,
    lockClose: true,
    actions: [
      {
        label: "ลองสู้ใหม่",
        primary: true,
        onClick: retryCurrentBattle
      },
      {
        label: isPracticeModeActive() ? "กลับหน้าหลัก" : "ไปเรียนบทนี้ใหม่",
        onClick: isPracticeModeActive() ? returnFromPracticeMode : returnToCurrentLessonFromDefeat
      }
    ]
  });
}

function retryCurrentBattle() {
  const battle = state.actBattle;
  const stageIndex = battle?.reviewStageIndex ?? state.actStageIndex;
  closeGameModal();
  cleanupBattleInputState();
  state.actBattle = null;
  state.currentBattleStats = null;
  state.playerHp = 100;
  state.enemyHp = 100;
  runSceneTransition("ลุกขึ้นอีกครั้ง การต่อสู้เริ่มใหม่...", () => startActBattle(stageIndex));
}

function returnToCurrentLessonFromDefeat() {
  const battle = state.actBattle;
  const stageIndex = battle?.reviewStageIndex ?? state.actStageIndex;
  closeGameModal();
  cleanupBattleInputState();
  state.actBattle = null;
  state.currentBattleStats = null;
  state.playerHp = 100;
  state.enemyHp = 100;
  restoreLessonUIAfterBattle();
  runSceneTransition("กลับไปทบทวนบทเรียนอีกครั้ง...", () => {
    showStageLesson(stageIndex, { lessonStepIndex: 0, dialogueIndex: 0 });
  });
}

const ACT_MAX_AP = 5;

const BATTLE_ITEMS = [
  {
    id: "hp_potion",
    name: "ยาฟื้นพลังชีวิต",
    image: "assets/items/hp_potion.png",
    description: "ฟื้น HP +30",
    fullDescription: "ฟื้นพลังชีวิตของผู้เล่น 30 หน่วย ใช้แล้วเสีย 1 เทิร์น",
    startingQuantity: 2,
    effectType: "restoreHp",
    value: 30
  },
  {
    id: "ap_potion",
    name: "ยาฟื้นพลัง AP",
    image: "assets/items/ap_potion.png",
    description: "ฟื้น AP +2",
    fullDescription: "ฟื้น AP ของผู้เล่น 2 หน่วย ใช้แล้วเสีย 1 เทิร์น",
    startingQuantity: 2,
    effectType: "restoreAp",
    value: 2
  },
  {
    id: "attack_boost_potion",
    name: "ยาเพิ่มพลังโจมตี",
    image: "assets/items/attack_boost_potion.png",
    description: "เพิ่มพลังโจมตีครั้งถัดไป x2",
    fullDescription: "เพิ่มพลังโจมตีของผู้เล่นเป็น 2 เท่าในการโจมตีครั้งถัดไป ใช้แล้วเสีย 1 เทิร์น",
    startingQuantity: 1,
    effectType: "nextAttackMultiplier",
    value: 2
  }
];

function createInitialBattleItemCounts() {
  return BATTLE_ITEMS.reduce((items, item) => {
    items[item.id] = item.startingQuantity;
    return items;
  }, {});
}

function getBattleItemById(itemId) {
  return BATTLE_ITEMS.find(item => item.id === itemId) || null;
}

function ensureBattleItemState(battle = state.actBattle) {
  if (!battle) {
    return null;
  }
  if (!battle.items || typeof battle.items !== "object" || Array.isArray(battle.items)) {
    battle.items = createInitialBattleItemCounts();
  }
  BATTLE_ITEMS.forEach(item => {
    const current = Number(battle.items[item.id]);
    if (!Number.isFinite(current)) {
      battle.items[item.id] = item.startingQuantity;
    } else {
      battle.items[item.id] = Math.max(0, Math.round(current));
    }
  });
  battle.attackBoostActive = Boolean(battle.attackBoostActive);
  battle.nextAttackMultiplier = Math.max(1, Number(battle.nextAttackMultiplier || 1));
  if (!battle.attackBoostActive && battle.nextAttackMultiplier > 1) {
    battle.attackBoostActive = true;
  }
  if (battle.attackBoostActive && battle.nextAttackMultiplier <= 1) {
    battle.nextAttackMultiplier = 2;
  }
  return battle;
}

function getBattleItemCount(itemId, battle = state.actBattle) {
  const activeBattle = ensureBattleItemState(battle);
  return Math.max(0, Number(activeBattle?.items?.[itemId] || 0));
}

function decreaseBattleItemCount(itemId, battle = state.actBattle) {
  const activeBattle = ensureBattleItemState(battle);
  if (!activeBattle?.items) {
    return 0;
  }
  activeBattle.items[itemId] = Math.max(0, getBattleItemCount(itemId, activeBattle) - 1);
  return activeBattle.items[itemId];
}

function isBattleAttackBoostReady(battle = state.actBattle) {
  const activeBattle = ensureBattleItemState(battle);
  return Boolean(activeBattle?.attackBoostActive || Number(activeBattle?.nextAttackMultiplier || 1) > 1);
}

function updateBattleBoostStatus() {
  if (!els.battleBoostStatus) {
    return;
  }
  const isReady = isBattleAttackBoostReady(state.actBattle);
  els.battleBoostStatus.classList.toggle("hidden", !isReady);
  els.battleBoostStatus.textContent = isReady ? "พลังโจมตี x2 พร้อมใช้" : "";
}

function consumeBattleAttackBoost(rawDamage, lines = []) {
  const battle = ensureBattleItemState(state.actBattle);
  const damage = Math.max(0, Math.round(Number(rawDamage) || 0));
  if (!battle || damage <= 0 || !isBattleAttackBoostReady(battle)) {
    return {
      damage,
      applied: false,
      multiplier: 1
    };
  }
  const multiplier = Math.max(1, Number(battle.nextAttackMultiplier || 2));
  const boostedDamage = Math.max(1, Math.round(damage * multiplier));
  battle.attackBoostActive = false;
  battle.nextAttackMultiplier = 1;
  addBattleMessageLine(lines, "พลังโจมตี x2 ทำงาน!");
  updateBattleBoostStatus();
  return {
    damage: boostedDamage,
    applied: true,
    multiplier
  };
}

function normalizeBossBalanceKey(stage) {
  const raw = [
    stage?.id,
    stage?.enemy,
    stage?.enemyId,
    stage?.bossId,
    stage?.title,
    stage?.thaiEnemy
  ]
    .filter(Boolean)
    .join(" ")
    .toLowerCase();

  if (raw.includes("time") && raw.includes("dust")) {
    return "timeDust";
  }
  if (raw.includes("echo") && raw.includes("tick")) {
    return "echoTick";
  }
  if (raw.includes("echo") && raw.includes("trick")) {
    return "echoTrick";
  }
  if (raw.includes("forger") || raw.includes("ed-forger") || raw.includes("-ed")) {
    return "edForger";
  }
  if (raw.includes("yesterday") && raw.includes("sprite")) {
    return "yesterdaySprite";
  }
  if (raw.includes("yesterday") && raw.includes("spirit")) {
    return "yesterdaySpirit";
  }
  if (raw.includes("ภูติเมื่อวาน") || raw.includes("ภูตเมื่อวาน")) {
    return "yesterdaySprite";
  }

  return "";
}

function getBalancedBossMaxHp(stage, baseHp = 100) {
  const configuredHp = ACT1_ENCOUNTER_MAX_HP[String(stage?.id || "")];
  if (Number.isFinite(configuredHp) && configuredHp > 0) {
    return configuredHp;
  }
  const normalizedBaseHp = Math.max(1, Number(stage?.enemyMaxHp || stage?.maxHp || stage?.hp || baseHp) || baseHp);
  if (isFinalBossStage(stage)) {
    return normalizedBaseHp;
  }

  if (PHASE1_STARTER_STAGE_IDS.has(stage?.id)) {
    return normalizedBaseHp;
  }

  const bossKey = normalizeBossBalanceKey(stage);
  const balance = EARLY_BOSS_BALANCE[bossKey];
  if (!balance) {
    return normalizedBaseHp;
  }

  const multipliedHp = Math.round(normalizedBaseHp * (balance.hpMultiplier || 1));
  const minHp = Number(balance.minMaxHp || normalizedBaseHp);
  const balancedMaxHp = Math.max(normalizedBaseHp, minHp, multipliedHp);
  console.log("[Balance] boss hp", {
    stageId: stage?.id,
    enemy: stage?.enemy,
    baseHp: normalizedBaseHp,
    balancedMaxHp
  });
  return balancedMaxHp;
}

function applyFocusBuffFromMeditation() {
  const battle = state.actBattle;
  if (!battle) {
    return null;
  }

  const hadActiveBuff = Boolean(battle.focusBuff?.active);
  battle.focusBuff = {
    active: true,
    bonusPercent: FOCUS_BALANCE_CONFIG.focusDamageBonusPercent,
    stacks: FOCUS_BALANCE_CONFIG.maxFocusStacks,
    source: "meditation",
    appliesToNextAttackOnly: FOCUS_BALANCE_CONFIG.buffAppliesToNextAttackOnly,
    improveCharmRoll: true
  };
  battle.consecutiveFocusUses = (battle.consecutiveFocusUses || 0) + 1;
  return { hadActiveBuff, focusBuff: battle.focusBuff };
}

function applyFocusBonusToDamage(baseDamage, focusBuff = null) {
  if (!focusBuff?.active) {
    return {
      damage: baseDamage,
      focusBonusDamage: 0,
      focusBonusPercent: 0
    };
  }

  const focusBonusPercent = Math.min(
    Number(focusBuff.bonusPercent || 0),
    FOCUS_BALANCE_CONFIG.focusDamageBonusPercent
  );
  const focusBonusDamage = Math.round(baseDamage * (focusBonusPercent / 100));
  const damage = baseDamage + focusBonusDamage;
  console.log("[FocusBalance] applied to damage", {
    baseDamage,
    focusBonusPercent,
    focusBonusDamage,
    finalDamage: damage
  });
  return {
    damage,
    focusBonusDamage,
    focusBonusPercent
  };
}

function capCombinedDamageBonus(baseDamage, bonuses = {}) {
  const focusPercent = Number(bonuses.focusPercent || 0);
  const chargePercent = Number(bonuses.chargePercent || 0);
  const totalPercent = Math.min(
    focusPercent + chargePercent,
    FOCUS_BALANCE_CONFIG.maxCombinedBonusPercent
  );
  const bonusDamage = Math.round(baseDamage * (totalPercent / 100));
  return {
    totalPercent,
    bonusDamage,
    finalDamage: baseDamage + bonusDamage
  };
}

function clearFocusBuffAfterAttack(battle) {
  if (!battle?.focusBuff) {
    return;
  }
  battle.focusBuff.active = false;
  battle.focusBuff.stacks = 0;
  battle.focusBuff.bonusPercent = 0;
  battle.focusBuff = null;
  battle.consecutiveFocusUses = 0;
}

function getActBattle() {
  return state.actBattle;
}

function ensureBattleCharmEffectState(battle = getActBattle()) {
  if (!battle) {
    return null;
  }
  if (!battle.charmEffectState || typeof battle.charmEffectState !== "object" || Array.isArray(battle.charmEffectState)) {
    battle.charmEffectState = {};
  }
  battle.bonusMaxAp = Math.max(0, Number(battle.bonusMaxAp) || 0);
  battle.charmEffectState.battleStartApApplied = Boolean(battle.charmEffectState.battleStartApApplied);
  battle.charmEffectState.maxApBonusApplied = Boolean(battle.charmEffectState.maxApBonusApplied);
  battle.charmEffectState.comebackApTriggered = Boolean(battle.charmEffectState.comebackApTriggered);
  battle.charmEffectState.focusSuccessApBonus = Math.max(0, Number(battle.charmEffectState.focusSuccessApBonus) || 0);
  battle.charmEffectState.focusCooldownReduction = Math.max(0, Number(battle.charmEffectState.focusCooldownReduction) || 0);
  battle.charmEffectState.turnCooldownInterval = Math.max(0, Number(battle.charmEffectState.turnCooldownInterval) || 0);
  battle.charmEffectState.turnCooldownReduction = Math.max(0, Number(battle.charmEffectState.turnCooldownReduction) || 0);
  battle.charmEffectState.lastTurnCooldownTrigger = Math.max(0, Number(battle.charmEffectState.lastTurnCooldownTrigger) || 0);
  battle.charmEffectState.lowHpApRestore = Math.max(0, Number(battle.charmEffectState.lowHpApRestore) || 0);
  battle.charmEffectState.lowHpApThreshold = Math.max(0, Number(battle.charmEffectState.lowHpApThreshold) || 0);
  return battle.charmEffectState;
}

function ensureBattleApEconomyState(battle = getActBattle()) {
  if (!battle) {
    return null;
  }
  ensureBattleCharmEffectState(battle);
  if (!battle.charmBattleFlags || typeof battle.charmBattleFlags !== "object" || Array.isArray(battle.charmBattleFlags)) {
    battle.charmBattleFlags = {};
  }
  battle.charmBattleFlags.emptyCoreCupUsed = Boolean(battle.charmBattleFlags.emptyCoreCupUsed);
  battle.charmBattleFlags.doubleTurnCupUsed = Boolean(battle.charmBattleFlags.doubleTurnCupUsed);
  battle.charmBattleFlags.perfectTurnCupUsed = Boolean(battle.charmBattleFlags.perfectTurnCupUsed);
  if (!battle.playerBuffs || typeof battle.playerBuffs !== "object" || Array.isArray(battle.playerBuffs)) {
    battle.playerBuffs = {};
  }
  battle.playerBuffs.nextFocusApBonus = Math.max(0, Number(battle.playerBuffs.nextFocusApBonus) || 0);
  battle.isBonusTurn = Boolean(battle.isBonusTurn);
  return battle;
}

function getActMaxAP(battle = getActBattle()) {
  if (!battle) {
    return ACT_MAX_AP;
  }
  ensureBattleCharmEffectState(battle);
  return Math.max(ACT_MAX_AP, ACT_MAX_AP + Math.max(0, Number(battle.bonusMaxAp) || 0));
}

function getActAP() {
  const battle = getActBattle();
  return battle ? clamp(Number(battle.ap ?? battle.playerAp ?? 0), 0, getActMaxAP(battle)) : 0;
}

function setActAP(value) {
  const battle = getActBattle();
  if (!battle) {
    updateActAPUI();
    return;
  }
  const nextAp = clamp(Number(value || 0), 0, getActMaxAP(battle));
  battle.ap = nextAp;
  if (typeof battle.playerAp === "number") {
    battle.playerAp = nextAp;
  }
  updateActAPUI();
  updateActActionMenuState();
}

function restorePlayerAp(amount, reason = "", options = {}) {
  const battle = getActBattle();
  if (!battle) {
    return { before: 0, after: 0, gained: 0, max: ACT_MAX_AP, reason };
  }
  ensureBattleApEconomyState(battle);
  const before = getActAP();
  const max = getActMaxAP(battle);
  const safeAmount = Math.max(0, Number(amount) || 0);
  if (safeAmount <= 0) {
    return { before, after: before, gained: 0, max, reason };
  }
  setActAP(before + safeAmount);
  const after = getActAP();
  const gained = Math.max(0, after - before);
  if (options.updateStats !== false) {
    updateBattleStats();
  }
  if (options.captureCheckpoint && playerData && getActiveSceneName() === "battle") {
    saveProgress({}, {
      source: reason || "apRestore",
      captureCheckpoint: true
    });
  }
  return { before, after, gained, max, reason };
}

function gainActAP(amount, reason = "") {
  return restorePlayerAp(amount, reason, { updateStats: false }).gained;
}

function spendActAP(cost) {
  const battle = getActBattle();
  if (!battle) {
    return false;
  }
  if (getActAP() < cost) {
    return false;
  }
  setActAP(getActAP() - cost);
  return true;
}

function updateActAPUI() {
  if (!els.playerApPips) {
    return;
  }

  if (!state.actBattle) {
    els.playerApPips.classList.add("hidden");
    els.playerApPips.innerHTML = "";
    return;
  }

  els.playerApPips.classList.remove("hidden");
  const ap = getActAP();
  const maxAp = getActMaxAP(state.actBattle);
  els.playerApPips.innerHTML = "";
  for (let index = 0; index < maxAp; index += 1) {
    const pip = document.createElement("span");
    pip.className = `ap-pip${index < ap ? " is-filled" : ""}`;
    els.playerApPips.appendChild(pip);
  }
}

function updateActActionMenuState() {
  const battle = getActBattle();
  if (!battle || !els.actionMenu || els.actionMenu.classList.contains("hidden")) {
    return;
  }

  const ap = getActAP();
  const canChoose = !battle.actionChoiceLocked && !isActBattleEnded(battle);
  setButtonEnabled(els.attackButton, canChoose && ap >= 1 && !battle.attackQuestionsExhausted);
  setButtonEnabled(els.itemButton, canChoose);
  setButtonEnabled(els.focusButton, canChoose);
  els.focusButton.classList.toggle("is-focus-hint", ap <= 0);
}

function clearBattleRecoveryActions() {
  els.actionMenu?.querySelectorAll(".battle-recovery-action").forEach(button => button.remove());
}

function addBattleRecoveryAction(label, onClick, className = "action-button") {
  if (!els.actionMenu) {
    return;
  }
  const button = document.createElement("button");
  button.type = "button";
  button.className = `${className} battle-recovery-action`;
  button.textContent = label;
  button.addEventListener("click", event => {
    event.preventDefault();
    event.stopPropagation();
    if (button.disabled) {
      return;
    }
    button.disabled = true;
    onClick();
  });
  els.actionMenu.appendChild(button);
}

function restartCurrentActBattle() {
  const battle = state.actBattle;
  const stage = battle?.stage;
  const stageIndex = getStageIndexById(stage?.id);
  if (!battle || !stage || stageIndex < 0) {
    return;
  }

  const returnContext = battle.returnContext || createFallbackBattleReturnContext(stage, {
    stageId: stage.id,
    reviewDialogueIndex: battle.reviewDialogueIndex,
    reviewLessonStepIndex: battle.reviewLessonStepIndex
  });
  state.pendingBattleReturnContext = returnContext;
  cleanupBossHeavyAttackChain({ clearParryUi: true });
  cleanupBattleInputState();
  cleanupBattleSkillEffects();
  resetBattleContinueControls();
  resetBattleActiveEffects();
  clearBattleRecoveryActions();
  state.actBattle = null;
  state.currentBattleStats = null;
  state.currentQuestion = null;
  state.parryAttack = null;
  runSceneTransition("เริ่ม battle ใหม่...", () => startActBattle(stageIndex));
}

function showBattleQuestionExhaustedRecovery(message = "") {
  const battle = state.actBattle;
  if (!battle) {
    return;
  }

  battle.advanceQuestionOnContinue = false;
  battle.actionChoiceLocked = false;
  battle.currentQuestion = null;
  battle.currentFocusQuestion = null;
  battle.attackQuestionsExhausted = true;
  setBattleTurnOwner("player");
  showOnlyBattlePanel(els.actionMenu);
  clearBattleRecoveryActions();
  els.battleMessage.textContent = message ||
    "โจทย์โจมตีใน battle นี้ถูกใช้ครบแล้ว ไม่มีการวนคำถามซ้ำ เลือกตั้งสมาธิ สู้ใหม่ หรือกลับไปบทเรียน";
  if (els.activityFeedback) {
    els.activityFeedback.textContent = "ระบบยังไม่วนโจทย์ซ้ำใน battle เดิม แต่มีทางเลือกให้กู้สถานการณ์ได้";
  }

  addBattleRecoveryAction("ตั้งสมาธิ", () => {
    battle.actionChoiceLocked = false;
    chooseActPlayerActionOnce(startActFocusAction);
  });
  addBattleRecoveryAction("เริ่ม battle ใหม่", restartCurrentActBattle);
  addBattleRecoveryAction("กลับไปบทเรียน", () => {
    runSceneTransition("กลับสู่บทเรียน...", exitBattleToReturnContext);
  });
  updateActActionMenuState();
}

function canChooseActPlayerAction() {
  const battle = state.actBattle;
  if (!battle || isActBattleEnded(battle)) {
    return false;
  }
  if (!els.actionMenu || els.actionMenu.classList.contains("hidden")) {
    return false;
  }
  if (battle.actionChoiceLocked || battle.skillFlowLocked || battle.awaitingGrammarCharge || battle.pendingBossTurn || battle.pendingBossAction) {
    return false;
  }
  return battle.playerActionPhase === "question";
}

function chooseActPlayerActionOnce(actionHandler) {
  const battle = state.actBattle;
  if (!canChooseActPlayerAction()) {
    return false;
  }
  battle.actionChoiceLocked = true;
  setActionButtonsEnabled(false);
  actionHandler();
  return true;
}

function beginActPlayerTurn(message = "", options = {}) {
  const battle = getActBattle();
  if (!battle) {
    return;
  }
  if (isActBattleEnded(battle)) {
    console.log("[Battle] beginActPlayerTurn blocked because battle already ended");
    return;
  }

  setBattleTurnOwner("player");
  ensureBattleSkillCooldownState(battle);
  ensureBattleItemState(battle);
  ensureBattleApEconomyState(battle);
  if (!options.preservePlayerTurnCounter) {
    battle.playerTurnCounter = Math.max(0, Number(battle.playerTurnCounter) || 0) + 1;
  }
  const playerTurnCharmLines = applyPlayerTurnCooldownCharmEffects(battle);
  battle.pendingPlayerAttack = null;
  if (BATTLE_FLOW_V2_CONFIG.enabled) {
    resetBattleFlowV2Selection({ phase: "question", cleanupCharge: true });
  }
  battle.pendingBossAction = null;
  battle.pendingBossTurn = null;
  battle.bossIntentReadyConsumed = false;
  battle.actionChoiceLocked = false;
  battle.awaitingParry = false;
  battle.awaitingPrepare = false;
  battle.playerActionPhase = "question";
  battle.currentQuestion = null;
  battle.currentFocusQuestion = null;
  battle.attackQuestionsExhausted = !hasAvailableBattleQuestion(battle.stage, "attack");
  if (battle.attackQuestionsExhausted) {
    showBattleQuestionExhaustedRecovery("โจทย์โจมตีใน battle นี้ถูกใช้ครบแล้ว ไม่มีการวนคำถามซ้ำ เลือกตั้งสมาธิ สู้ใหม่ หรือกลับไปบทเรียน");
    updateBattleStats();
    return;
  }
  clearBattleRecoveryActions();
  showOnlyBattlePanel(els.actionMenu);
  resetBattleContinueControls();
  els.continueBattleButton.classList.add("hidden");
  const baseMessage = message || (getActAP() <= 0
    ? "AP หมดชั่วคราว ใช้ตั้งสมาธิเพื่อฟื้น AP"
    : `${battle.stage.title} - เลือกการกระทำ`);
  els.battleMessage.textContent = playerTurnCharmLines.length
    ? `${baseMessage}\n${playerTurnCharmLines.join("\n")}`
    : baseMessage;
  updateBattleStats();
  updateActActionMenuState();
}

function clearEnemyTurnTimer() {
  if (state.enemyTurnTimer) {
    clearTimeout(state.enemyTurnTimer);
    state.enemyTurnTimer = null;
  }
}

function clamp(value, min, max) {
  return Math.max(min, Math.min(max, value));
}

function sample(array, count) {
  const copy = [...array];
  const result = [];

  while (copy.length && result.length < count) {
    const index = Math.floor(Math.random() * copy.length);
    result.push(copy.splice(index, 1)[0]);
  }

  return result;
}

function shuffleArray(array) {
  const copy = [...array];
  for (let index = copy.length - 1; index > 0; index -= 1) {
    const swapIndex = Math.floor(Math.random() * (index + 1));
    [copy[index], copy[swapIndex]] = [copy[swapIndex], copy[index]];
  }
  return copy;
}

function getQuestionId(question, index = 0, prefix = "q") {
  if (question?.id) {
    return question.id;
  }

  const text = question?.prompt || question?.sentence || question?.baseVerb || "question";
  const answer = question?.answer || question?.correctAnswer || question?.correct || "answer";
  const ruleId = question?.ruleId || "rule";
  const lessonId = question?.lessonId || "lesson";
  return [
    prefix,
    lessonId,
    ruleId,
    index,
    String(text).slice(0, 40),
    String(answer).slice(0, 24)
  ].join("-");
}

function getQuestionStableKey(question, fallbackPrefix = "question") {
  if (question?.id) {
    return String(question.id);
  }
  const prompt = question?.prompt || question?.sentence || question?.question || question?.text || "";
  const answer = question?.answer ?? question?.correctAnswer ?? question?.correct ?? question?.v2 ?? "";
  if (prompt && answer !== "") {
    return `${fallbackPrefix}:${prompt}::${answer}`;
  }
  if (prompt) {
    return `${fallbackPrefix}:${prompt}`;
  }
  return `${fallbackPrefix}:${JSON.stringify(question || {}).slice(0, 120)}`;
}

function createQuestionRepeatHistory() {
  return {
    usedQuestionKeys: new Set(),
    wrongQuestionKeys: new Set(),
    correctQuestionKeys: new Set(),
    repeatQuestionKeys: new Set(),
    repeatCycle: 0,
    repeatNoticeShown: false
  };
}

function ensureQuestionRepeatHistory(history) {
  const safeHistory = history && typeof history === "object" ? history : createQuestionRepeatHistory();
  ["usedQuestionKeys", "wrongQuestionKeys", "correctQuestionKeys", "repeatQuestionKeys"].forEach(key => {
    safeHistory[key] = safeHistory[key] instanceof Set ? safeHistory[key] : restoreSet(safeHistory[key]);
  });
  safeHistory.repeatCycle = Math.max(0, Number(safeHistory.repeatCycle) || 0);
  safeHistory.repeatNoticeShown = Boolean(safeHistory.repeatNoticeShown);
  return safeHistory;
}

function getBattleQuestionRepeatHistory(context = "attack", battle = state.actBattle) {
  if (!battle) {
    return createQuestionRepeatHistory();
  }
  const field = context === "focus"
    ? "focusQuestionHistory"
    : context === "boss" ? "bossQuestionHistory" : "attackQuestionHistory";
  battle[field] = ensureQuestionRepeatHistory(battle[field]);
  return battle[field];
}

function markQuestionResult(question, result, history, prefix = "question") {
  if (!question || !history) {
    return;
  }
  const safeHistory = ensureQuestionRepeatHistory(history);
  const key = getQuestionStableKey(question, prefix);
  safeHistory.usedQuestionKeys.add(key);
  if (result === "correct") {
    safeHistory.correctQuestionKeys.add(key);
  } else if (result === "wrong") {
    safeHistory.wrongQuestionKeys.add(key);
  }
}

function pickRandomItem(items) {
  if (!Array.isArray(items) || !items.length) {
    return null;
  }
  return items[Math.floor(Math.random() * items.length)] || null;
}

function pickQuestionWithSmartRepeat(questionEntries, history, prefix = "battle") {
  const safeHistory = ensureQuestionRepeatHistory(history);
  const uniqueEntries = [];
  const knownKeys = new Set();
  (questionEntries || []).forEach(entry => {
    const question = entry?.question || entry;
    if (!question || typeof question !== "object") {
      return;
    }
    const key = getQuestionStableKey(question, prefix);
    if (!knownKeys.has(key)) {
      knownKeys.add(key);
      uniqueEntries.push({ ...(entry?.question ? entry : { question }), key });
    }
  });
  if (!uniqueEntries.length) {
    return null;
  }

  const unused = uniqueEntries.filter(entry => !safeHistory.usedQuestionKeys.has(entry.key));
  if (unused.length) {
    const picked = pickRandomItem(unused);
    safeHistory.usedQuestionKeys.add(picked.key);
    return { ...picked, repeatMode: false, repeatReason: "unused", repeatNoticeJustStarted: false };
  }

  const repeatNoticeJustStarted = !safeHistory.repeatNoticeShown;
  safeHistory.repeatNoticeShown = true;
  let wrongPool = uniqueEntries.filter(entry =>
    safeHistory.wrongQuestionKeys.has(entry.key) && !safeHistory.repeatQuestionKeys.has(entry.key)
  );
  let generalPool = uniqueEntries.filter(entry =>
    safeHistory.usedQuestionKeys.has(entry.key) && !safeHistory.repeatQuestionKeys.has(entry.key)
  );
  let repeatReason = "wrong-first";
  let picked = pickRandomItem(wrongPool);

  if (!picked) {
    repeatReason = "general-repeat";
    picked = pickRandomItem(generalPool);
  }
  if (!picked) {
    safeHistory.repeatQuestionKeys.clear();
    safeHistory.repeatCycle += 1;
    wrongPool = uniqueEntries.filter(entry => safeHistory.wrongQuestionKeys.has(entry.key));
    generalPool = uniqueEntries.filter(entry => safeHistory.usedQuestionKeys.has(entry.key));
    picked = pickRandomItem(wrongPool);
    repeatReason = picked ? "wrong-first-new-cycle" : "general-new-cycle";
    if (!picked) {
      picked = pickRandomItem(generalPool.length ? generalPool : uniqueEntries);
    }
  }
  if (!picked) {
    return null;
  }
  safeHistory.repeatQuestionKeys.add(picked.key);
  return { ...picked, repeatMode: true, repeatReason, repeatNoticeJustStarted };
}

function prepareQuestion(rawQuestion, index = 0) {
  const rawOptions = getRawBattleQuestionOptions(rawQuestion);
  const options = getActBattleQuestionType(rawQuestion) === "multiple-choice"
    ? ensureEnoughBattleDistractors(rawQuestion, rawOptions, getBattleCorrectAnswer(rawQuestion))
    : normalizeBattleOptions(rawOptions);
  return {
    ...rawQuestion,
    id: getQuestionId(rawQuestion, index),
    correctAnswer: getBattleCorrectAnswer(rawQuestion),
    options: shuffleArray(options)
  };
}

function normalizeBattleQuestionKeyPart(value = "") {
  return String(value ?? "").trim().toLowerCase().replace(/\s+/g, " ");
}

function getBattleQuestionAnswer(question = {}) {
  return question.correctAnswer ?? question.answer ?? question.correct ?? question.v2 ?? "";
}

function getBattleQuestionPromptSource(question = {}) {
  return question.prompt ?? question.text ?? question.sentence ?? question.question ?? "";
}

function getBattleQuestionBaseSource(question = {}) {
  return question.baseVerb ?? question.targetWord ?? question.v1 ?? question.word?.v1 ?? "";
}

function getBattleQuestionKeys(question, index = 0, prefix = "battle") {
  if (!question) {
    return [];
  }

  const keys = [];
  const addKey = (type, ...parts) => {
    const normalizedParts = parts.map(normalizeBattleQuestionKeyPart).filter(Boolean);
    if (!normalizedParts.length) {
      return;
    }
    const key = `${type}:${normalizedParts.join("=>")}`;
    if (!keys.includes(key)) {
      keys.push(key);
    }
  };

  addKey("id", question.id);
  addKey("questionId", question.questionId);
  addKey("generatedId", getQuestionId(question, index, prefix));

  const answer = getBattleQuestionAnswer(question);
  const prompt = getBattleQuestionPromptSource(question);
  const baseWord = getBattleQuestionBaseSource(question);
  addKey("prompt-answer", prompt, answer);
  addKey("base-answer", baseWord, answer);
  addKey("sentence-answer", question.sentence, answer);
  addKey("word-answer", question.v1, question.v2);

  if (!keys.length) {
    addKey("fallback", JSON.stringify({
      prompt,
      baseWord,
      answer,
      type: question.type || "",
      ruleId: question.ruleId || "",
      lessonId: question.lessonId || ""
    }));
  }

  return keys;
}

function ensureBattleQuestionHistory(battle = state.actBattle) {
  if (!battle) {
    return new Set();
  }
  if (!(battle.usedQuestionKeys instanceof Set)) {
    battle.usedQuestionKeys = restoreSet(battle.usedQuestionKeys);
  }
  return battle.usedQuestionKeys;
}

function hasUsedBattleQuestion(question, battle = state.actBattle, index = 0, prefix = "battle") {
  const usedKeys = ensureBattleQuestionHistory(battle);
  return getBattleQuestionKeys(question, index, prefix).some(key => usedKeys.has(key));
}

function markBattleQuestionUsed(question, battle = state.actBattle, index = 0, prefix = "battle") {
  const usedKeys = ensureBattleQuestionHistory(battle);
  getBattleQuestionKeys(question, index, prefix).forEach(key => usedKeys.add(key));
}

function markBattleQuestionIdsAsUsed(ids, battle = state.actBattle) {
  const usedKeys = ensureBattleQuestionHistory(battle);
  (ids || []).forEach(id => {
    const normalizedId = normalizeBattleQuestionKeyPart(id);
    if (normalizedId) {
      usedKeys.add(`id:${normalizedId}`);
      usedKeys.add(`generatedId:${normalizedId}`);
    }
  });
}

function pickUnusedBattleQuestionEntry(pool, {
  battle = state.actBattle,
  usedSet = null,
  lastBaseVerb = "",
  prefix = "battle"
} = {}) {
  if (!pool || !pool.length) {
    return null;
  }

  const normalizedLastBaseVerb = normalizeBattleQuestionKeyPart(lastBaseVerb);
  const candidates = pool
    .map((question, index) => ({ question, index }))
    .filter(({ question, index }) => {
      const generatedId = getQuestionId(question, index, prefix);
      if (usedSet?.has(generatedId)) {
        return false;
      }
      return !hasUsedBattleQuestion(question, battle, index, prefix);
    });

  if (!candidates.length) {
    return null;
  }

  const withoutSameVerb = candidates.filter(({ question }) => {
    const baseWord = normalizeBattleQuestionKeyPart(getQuestionBaseWord(question) || getBattleQuestionBaseSource(question));
    return !baseWord || baseWord !== normalizedLastBaseVerb;
  });
  const finalCandidates = withoutSameVerb.length ? withoutSameVerb : candidates;
  return sample(finalCandidates, 1)[0] || null;
}

function pickUnusedBattleQuestion(pool, options = {}) {
  return pickUnusedBattleQuestionEntry(pool, options)?.question || null;
}

function makeStageReviewQuestion(stageId, ruleId, id, prompt, options, answer, explanation = "") {
  return {
    id: `review-${stageId}-${id}`,
    lessonId: stageId,
    ruleId,
    prompt,
    options,
    answer,
    explanation
  };
}

