function createVsBossEvaluationSummary({ bossDefeated = false } = {}) {
  const practice = state.vsBossPractice;
  const battle = state.actBattle;
  const stats = battle?.grammariaStats || state.currentBattleStats || {};
  const correctAnswers = Math.max(0, Number(stats.correctAnswers) || 0);
  const wrongAnswers = Math.max(0, Number(stats.wrongAnswers) || 0);
  return {
    bossId: practice.bossId,
    correctAnswers,
    wrongAnswers,
    totalQuestions: correctAnswers + wrongAnswers,
    maxCombo: Math.max(0, Number(practice.evaluation?.maxCombo) || 0),
    damageDealt: Math.max(0, Number(stats.playerDamageDealt) || 0),
    damageTaken: Math.max(0, Number(stats.bossDamageDealt) || 0),
    turns: Math.max(1, Number(battle?.turnNumber) || 1),
    bossDefeated: Boolean(bossDefeated),
    playerHpRemaining: clamp(Number(state.playerHp) || 0, 0, 100),
    startedAt: practice.evaluation?.startedAt || Date.now(),
    endedAt: Date.now()
  };
}

function buildVsBossResultPanel(config, result, scoreSave, saveWarning = "") {
  const panel = document.createElement("div");
  panel.id = "vsBossPracticeResultModal";
  panel.className = "vs-boss-result-panel";
  const score = document.createElement("p");
  score.id = "vsBossPracticeResultScore";
  score.className = "vs-boss-score-highlight";
  score.textContent = `Grammaria ประเมินผล: ${result.score}`;
  const stats = document.createElement("div");
  stats.className = "vs-boss-result-stats";
  const rows = [
    ["Boss", config.name],
    ["หัวข้อ", config.topicTh],
    ["Accuracy", `${result.correctAnswers}/${result.totalQuestions} ข้อ`],
    ["คะแนนสูงสุดเดิม", String(scoreSave.previousBest)],
    ["คะแนนสูงสุดปัจจุบัน", String(scoreSave.bestScore)]
  ];
  rows.forEach(([label, value]) => {
    const row = document.createElement("p");
    const labelNode = document.createElement("span");
    labelNode.textContent = label;
    const valueNode = document.createElement("strong");
    valueNode.textContent = value;
    row.append(labelNode, valueNode);
    stats.appendChild(row);
  });
  const best = document.createElement("p");
  best.id = "vsBossPracticeBestScore";
  best.className = "vs-boss-result-record";
  best.textContent = scoreSave.isNewBest ? "สถิติใหม่!" : "ยังไม่ทำลายสถิติเดิม";
  const note = document.createElement("p");
  note.className = "vs-boss-result-note";
  note.textContent = "คะแนนนี้ใช้เพื่อประเมินผลการฝึกฝนเท่านั้น ไม่ถูกเพิ่มเข้า Grammaria จริง";
  panel.append(score, stats, best, note);
  if (saveWarning) {
    const warning = document.createElement("p");
    warning.className = "vs-bosses-status is-error";
    warning.textContent = saveWarning;
    panel.appendChild(warning);
  }
  return panel;
}

async function finishVsBossPracticeBattle({ bossDefeated = false } = {}) {
  const practice = state.vsBossPractice;
  if (!practice.active || practice.finishing) {
    return;
  }
  practice.finishing = true;
  const config = getVsBossConfig(practice.bossId);
  const summary = createVsBossEvaluationSummary({ bossDefeated });
  const result = {
    ...summary,
    score: calculateVsBossEvaluationScore(summary)
  };
  const localPrevious = Math.max(0, Number(practice.scores?.[practice.bossId]?.bestScore) || 0);
  let scoreSave = {
    previousBest: localPrevious,
    bestScore: Math.max(localPrevious, result.score),
    isNewBest: result.score > localPrevious
  };
  let saveWarning = "";
  cleanupManualBattleExitState();
  endPracticeMode({ restoreProgress: true });
  practice.active = false;
  practice.starting = false;
  practice.evaluation = null;
  try {
    scoreSave = await saveVsBossPracticeScore(config.id, result);
  } catch (error) {
    console.error("[VS Bosses] failed to save best score:", error);
    practice.scores = {
      ...practice.scores,
      [config.id]: createVsBossScoreEntry(practice.scores?.[config.id] || {}, result, (Number(practice.scores?.[config.id]?.attempts) || 0) + 1)
    };
    saveWarning = "ไม่สามารถบันทึกคะแนนสูงสุดได้ แต่คะแนนรอบนี้ยังแสดงอยู่";
  }
  practice.lastResult = { ...result, ...scoreSave };
  practice.finishing = false;
  renderVsBossesGrid();
  showScene("vsBosses");
  openGameModal({
    title: bossDefeated ? "ฝึกฝนกับบอสสำเร็จ" : "การฝึกฝนจบลง",
    body: bossDefeated
      ? `${config.name} พ่ายแพ้แล้ว`
      : "แม้ยังเอาชนะบอสไม่ได้ แต่คะแนนนี้ใช้วัดพัฒนาการของเจ้าได้",
    content: buildVsBossResultPanel(config, result, scoreSave, saveWarning),
    lockClose: true,
    actions: [
      { label: bossDefeated ? "ฝึกอีกครั้ง" : "ลองอีกครั้ง", primary: true, onClick: () => { closeGameModal(); startVsBossPracticeBattle(config.id); } },
      { label: "เลือกบอสอื่น", onClick: () => { closeGameModal(); openVsBossesScene(); } },
      { label: "กลับหน้าหลัก", onClick: () => { closeGameModal(); showMainMenu(); } }
    ]
  });
}

function startVsBossPracticeBattle(bossId) {
  if (state.isTransitioning || state.vsBossPractice.starting || state.vsBossPractice.active) {
    return;
  }
  const config = getVsBossConfig(bossId);
  const primaryStage = getVsBossPrimaryStage(config);
  const stageIndex = primaryStage ? getStageIndexById(primaryStage.id) : -1;
  const questionPool = getVsBossQuestionPool(bossId);
  const questionAnalysis = analyzeBattleQuestionPool(questionPool, primaryStage);
  if (!config || !primaryStage || stageIndex < 0 || !questionAnalysis.ok) {
    showBattleContentError(primaryStage || {
      id: bossId || "unknown-vs-boss",
      type: "mini-boss",
      title: config?.name || "VS Bosses",
      enemy: config?.name || ""
    }, {
      stageIndex,
      source: "vs-boss-selection",
      reason: !config || !primaryStage || stageIndex < 0
        ? "VS boss configuration is missing"
        : "VS boss question pool is empty or invalid",
      failures: questionAnalysis.failures,
      returnToVsBosses: true,
      retryAction: () => startVsBossPracticeBattle(bossId)
    });
    return;
  }
  state.vsBossPractice.starting = true;
  state.vsBossPractice.active = true;
  state.vsBossPractice.finishing = false;
  state.vsBossPractice.bossId = config.id;
  state.vsBossPractice.stageId = primaryStage.id;
  state.vsBossPractice.playerSnapshot = getVsBossPlayerBattleSnapshot();
  state.vsBossPractice.evaluation = {
    startedAt: Date.now(),
    currentCombo: 0,
    maxCombo: 0
  };
  beginPracticeMode(primaryStage, "vs-boss");
  closeGameModal();
  runSceneTransition(`กำลังเปิดสนามฝึกกับ ${config.name}...`, () => {
    try {
      startActBattle(stageIndex);
      state.vsBossPractice.starting = false;
    } catch (error) {
      console.error("[VS Bosses] failed to start practice:", error);
      state.vsBossPractice.active = false;
      state.vsBossPractice.starting = false;
      endPracticeMode({ restoreProgress: true });
      showScene("vsBosses");
      setVsBossesStatus("ไม่สามารถเริ่มโหมดฝึกฝนกับบอสได้", true);
    }
  });
}

function exitVsBossPracticeToSelection() {
  closeGameModal();
  cleanupManualBattleExitState();
  endPracticeMode({ restoreProgress: true });
  state.vsBossPractice.active = false;
  state.vsBossPractice.starting = false;
  state.vsBossPractice.finishing = false;
  state.vsBossPractice.evaluation = null;
  renderVsBossesGrid();
  showScene("vsBosses");
}

function normalizeVerbMemoryChoiceText(value) {
  return String(value ?? "")
    .trim()
    .toLowerCase()
    .replace(/\s*\/\s*/g, "/")
    .replace(/\s+/g, " ");
}

function normalizeVerbMemoryAnswer(value) {
  return normalizeVerbMemoryChoiceText(value);
}

function splitVerbMemoryVariants(value) {
  const combined = normalizeVerbMemoryChoiceText(value);
  if (!combined) {
    return [];
  }
  const variants = combined
    .split("/")
    .map(normalizeVerbMemoryChoiceText)
    .filter(Boolean);
  return [...new Set([combined, ...variants])];
}

function isSafeVerbMemoryOption(value) {
  const cleanValue = String(value || "").trim();
  return Boolean(cleanValue) && !VERB_MEMORY_FORBIDDEN_OPTION_PATTERN.test(cleanValue);
}

function shuffleVerbMemoryValues(values) {
  const shuffled = [...values];
  for (let index = shuffled.length - 1; index > 0; index -= 1) {
    const swapIndex = Math.floor(Math.random() * (index + 1));
    [shuffled[index], shuffled[swapIndex]] = [shuffled[swapIndex], shuffled[index]];
  }
  return shuffled;
}

function getVerbMemoryAcceptedAnswers(verb, slot) {
  const answers = Array.isArray(verb?.accepted?.[slot]) ? verb.accepted[slot] : [];
  const combined = [verb?.[slot], ...answers]
    .map(value => String(value || "").trim())
    .filter(Boolean);
  const seen = new Set();
  return combined.filter(answer => {
    const normalized = normalizeVerbMemoryAnswer(answer);
    if (!normalized || seen.has(normalized)) {
      return false;
    }
    seen.add(normalized);
    return true;
  });
}

function getVisibleVerbFormsForChallenge(verb, missingSlot) {
  const visibleForms = new Set();
  VERB_MEMORY_SLOTS
    .filter(slot => slot !== missingSlot)
    .forEach(slot => {
      splitVerbMemoryVariants(verb?.[slot]).forEach(variant => visibleForms.add(variant));
    });
  return [...visibleForms];
}

function buildVerbMemoryBannedChoiceSet(verb, missingSlot, correctAnswer, acceptedAnswers = []) {
  const bannedChoices = new Set(["", "undefined", "null", "todo", "wrong option", "distractor", "placeholder", "ตัวเลือกหลอก"]);
  [
    ...getVisibleVerbFormsForChallenge(verb, missingSlot),
    correctAnswer,
    ...acceptedAnswers
  ].forEach(value => {
    splitVerbMemoryVariants(value).forEach(variant => bannedChoices.add(variant));
  });
  return bannedChoices;
}

function isInvalidVerbMemoryChoice(choice, { bannedChoices, usedChoices, usedVariants } = {}) {
  const normalized = normalizeVerbMemoryChoiceText(choice);
  const variants = splitVerbMemoryVariants(choice);
  if (!isSafeVerbMemoryOption(choice) || !normalized || !variants.length) {
    return true;
  }
  if (usedChoices?.has(normalized)) {
    return true;
  }
  return variants.some(variant => bannedChoices?.has(variant) || usedVariants?.has(variant));
}

function getValidVerbMemoryMissingSlots(verb) {
  return VERB_MEMORY_SLOTS.filter(missingSlot => {
    const correctVariants = new Set(
      getVerbMemoryAcceptedAnswers(verb, missingSlot).flatMap(splitVerbMemoryVariants)
    );
    if (!correctVariants.size) {
      return false;
    }
    const visibleVariants = getVisibleVerbFormsForChallenge(verb, missingSlot);
    return !visibleVariants.some(variant => correctVariants.has(variant));
  });
}

function buildVerbMemoryRegularizedForms(v1) {
  const base = String(v1 || "").trim();
  if (!base) {
    return [];
  }
  const forms = [];
  if (/[^aeiou]y$/i.test(base)) {
    forms.push(`${base.slice(0, -1)}ied`);
  }
  if (/e$/i.test(base)) {
    forms.push(`${base}d`);
  } else {
    forms.push(`${base}ed`, `${base}d`);
  }
  if (/[^aeiou][aeiou][^aeiouwxy]$/i.test(base)) {
    forms.push(`${base}${base.slice(-1)}ed`);
  }
  return [...new Set(forms)];
}

function buildVerbMemorySpellingConfusions(verb) {
  const roots = [verb?.v1, verb?.v2, verb?.v3]
    .flatMap(splitVerbMemoryVariants)
    .filter(root => root && !root.includes("/"));
  const forms = [];
  roots.forEach(root => {
    forms.push(`${root}ed`, `${root}d`, `${root}en`);
  });
  splitVerbMemoryVariants(verb?.v2)
    .filter(root => !root.includes("/"))
    .forEach(root => forms.push(`${root}n`));
  return [...new Set(forms)];
}

function generateVerbMemoryChoices(verb, missingSlot) {
  const correctAnswer = String(verb?.[missingSlot] || "").trim();
  const acceptedAnswers = getVerbMemoryAcceptedAnswers(verb, missingSlot);
  const bannedChoices = buildVerbMemoryBannedChoiceSet(verb, missingSlot, correctAnswer, acceptedAnswers);
  const distractors = [];
  const usedChoices = new Set();
  const usedVariants = new Set();
  const addDistractor = value => {
    const cleanValue = String(value || "").trim();
    if (distractors.length >= 2 || isInvalidVerbMemoryChoice(cleanValue, { bannedChoices, usedChoices, usedVariants })) {
      return false;
    }
    usedChoices.add(normalizeVerbMemoryChoiceText(cleanValue));
    splitVerbMemoryVariants(cleanValue).forEach(variant => usedVariants.add(variant));
    distractors.push(cleanValue);
    return true;
  };
  const addFirstValidDistractor = candidates => {
    for (const candidate of candidates) {
      if (addDistractor(candidate)) {
        return true;
      }
    }
    return false;
  };

  const regularizedCandidates = buildVerbMemoryRegularizedForms(verb?.v1);
  const otherVerbCandidates = shuffleVerbMemoryValues(IRREGULAR_VERB_MEMORY_BANK)
    .filter(otherVerb => otherVerb?.id !== verb?.id)
    .map(otherVerb => otherVerb?.[missingSlot]);
  const spellingCandidates = buildVerbMemorySpellingConfusions(verb);
  const fallbackCandidates = [
    `${String(verb?.v1 || "").trim()}ed`,
    `${String(verb?.v1 || "").trim()}d`,
    `${String(verb?.v1 || "").trim()}en`,
    `${String(verb?.v1 || "").trim()}ing`
  ];

  addFirstValidDistractor(regularizedCandidates);
  addFirstValidDistractor(otherVerbCandidates);

  [regularizedCandidates, otherVerbCandidates, spellingCandidates, fallbackCandidates]
    .forEach(candidates => candidates.forEach(addDistractor));

  if (!isSafeVerbMemoryOption(correctAnswer) || distractors.length !== 2) {
    return [];
  }
  return shuffleVerbMemoryValues([correctAnswer, ...distractors]);
}

function checkVerbMemoryAnswer(selectedAnswer, challenge) {
  const selected = normalizeVerbMemoryAnswer(selectedAnswer);
  if (!selected || !challenge) {
    return false;
  }
  const acceptedAnswers = [challenge.correctAnswer, ...(challenge.acceptedAnswers || [])];
  return acceptedAnswers.some(answer => normalizeVerbMemoryAnswer(answer) === selected);
}

function generateVerbMemoryChallenge() {
  if (!IRREGULAR_VERB_MEMORY_BANK.length) {
    return null;
  }
  const usableVerbs = IRREGULAR_VERB_MEMORY_BANK
    .map(verb => ({ verb, validMissingSlots: getValidVerbMemoryMissingSlots(verb) }))
    .filter(entry => entry.validMissingSlots.length);
  if (!usableVerbs.length) {
    return null;
  }
  const usedUsableVerbCount = usableVerbs.filter(entry => verbMemoryPracticeState.usedVerbIds.has(entry.verb.id)).length;
  if (usedUsableVerbCount >= usableVerbs.length) {
    verbMemoryPracticeState.usedVerbIds.clear();
  }
  let availableVerbs = usableVerbs.filter(entry => !verbMemoryPracticeState.usedVerbIds.has(entry.verb.id));
  if (!availableVerbs.length) {
    verbMemoryPracticeState.usedVerbIds.clear();
    availableVerbs = [...usableVerbs];
  }
  for (const entry of shuffleVerbMemoryValues(availableVerbs)) {
    for (const missingSlot of shuffleVerbMemoryValues(entry.validMissingSlots)) {
      const verb = entry.verb;
      const correctAnswer = String(verb?.[missingSlot] || "").trim();
      const choices = generateVerbMemoryChoices(verb, missingSlot);
      if (choices.length !== 3) {
        continue;
      }
      verbMemoryPracticeState.usedVerbIds.add(verb.id);
      return {
        verbId: verb.id,
        no: verb.no,
        v1: verb.v1,
        v2: verb.v2,
        v3: verb.v3,
        meaningTh: verb.meaningTh,
        missingSlot,
        correctAnswer,
        acceptedAnswers: getVerbMemoryAcceptedAnswers(verb, missingSlot),
        choices
      };
    }
  }
  return null;
}

function validateIrregularVerbMemoryBank() {
  const failures = [];
  const bank = IRREGULAR_VERB_MEMORY_BANK;
  if (!Array.isArray(bank)) {
    return { ok: false, count: 0, failures: ["IRREGULAR_VERB_MEMORY_BANK is not an array"] };
  }
  const ids = new Set();
  const numbers = new Set();
  const invalidValuePattern = /undefined|null|todo|placeholder|debug|wrong option|distractor|ตัวเลือกหลอก/i;
  bank.forEach((verb, index) => {
    const label = verb?.id || `item-${index + 1}`;
    ["id", "v1", "v2", "v3", "meaningTh"].forEach(field => {
      const value = String(verb?.[field] || "").trim();
      if (!value) {
        failures.push(`${label}: missing ${field}`);
      } else if (invalidValuePattern.test(value)) {
        failures.push(`${label}: invalid ${field}`);
      }
    });
    if (!Number.isFinite(Number(verb?.no))) {
      failures.push(`${label}: invalid no`);
    }
    if (ids.has(verb?.id)) {
      failures.push(`${label}: duplicate id`);
    }
    if (numbers.has(verb?.no)) {
      failures.push(`${label}: duplicate no`);
    }
    ids.add(verb?.id);
    numbers.add(verb?.no);

    VERB_MEMORY_SLOTS.forEach(slot => {
      const accepted = verb?.accepted?.[slot];
      if (!Array.isArray(accepted) || !accepted.length) {
        failures.push(`${label}: missing accepted.${slot}`);
        return;
      }
      accepted.forEach(answer => {
        const cleanAnswer = String(answer || "").trim();
        if (!cleanAnswer || invalidValuePattern.test(cleanAnswer)) {
          failures.push(`${label}: invalid accepted.${slot}`);
        }
      });
      const challenge = {
        correctAnswer: verb?.[slot],
        acceptedAnswers: getVerbMemoryAcceptedAnswers(verb, slot)
      };
      if (!checkVerbMemoryAnswer(verb?.[slot], challenge)) {
        failures.push(`${label}/${slot}: checker rejected correct answer`);
      }
      accepted.forEach(answer => {
        if (!checkVerbMemoryAnswer(answer, challenge)) {
          failures.push(`${label}/${slot}: checker rejected accepted answer ${answer}`);
        }
      });
    });
  });
  return {
    ok: failures.length === 0,
    count: bank.length,
    failures
  };
}

let verbMemoryChoiceValidationCache = null;

function validateVerbMemoryChoiceGeneration(options = {}) {
  const runsPerCase = clamp(Math.floor(Number(options.runsPerCase) || 12), 1, 100);
  if (verbMemoryChoiceValidationCache && !options.force && verbMemoryChoiceValidationCache.runsPerCase === runsPerCase) {
    return verbMemoryChoiceValidationCache;
  }
  const failures = [];
  const failureKeys = new Set();
  const skippedDetails = [];
  let checkedCases = 0;
  let generatedChoiceSets = 0;
  const addFailure = (verb, slot, message) => {
    const failure = `${verb?.id || "unknown"}/${slot}: ${message}`;
    if (!failureKeys.has(failure)) {
      failureKeys.add(failure);
      failures.push(failure);
    }
  };

  IRREGULAR_VERB_MEMORY_BANK.forEach(verb => {
    const validSlots = new Set(getValidVerbMemoryMissingSlots(verb));
    VERB_MEMORY_SLOTS.forEach(slot => {
      if (!validSlots.has(slot)) {
        skippedDetails.push({
          verbId: verb.id,
          missingSlot: slot,
          reason: "revealed-by-identical-visible-form"
        });
        return;
      }
      checkedCases += 1;
      const challenge = {
        correctAnswer: verb?.[slot],
        acceptedAnswers: getVerbMemoryAcceptedAnswers(verb, slot)
      };
      const visibleForms = new Set(getVisibleVerbFormsForChallenge(verb, slot));
      for (let run = 0; run < runsPerCase; run += 1) {
        const choices = generateVerbMemoryChoices(verb, slot);
        generatedChoiceSets += 1;
        if (choices.length !== 3) {
          addFailure(verb, slot, `generated ${choices.length} choices`);
          continue;
        }
        const normalizedChoices = choices.map(normalizeVerbMemoryChoiceText);
        if (new Set(normalizedChoices).size !== choices.length) {
          addFailure(verb, slot, "duplicate normalized choices");
        }
        if (choices.some(choice => !isSafeVerbMemoryOption(choice))) {
          addFailure(verb, slot, "empty or placeholder choice");
        }
        const correctChoiceCount = choices.filter(choice => checkVerbMemoryAnswer(choice, challenge)).length;
        if (correctChoiceCount !== 1) {
          addFailure(verb, slot, `correct choice count ${correctChoiceCount}`);
        }
        choices.forEach(choice => {
          if (checkVerbMemoryAnswer(choice, challenge)) {
            return;
          }
          if (splitVerbMemoryVariants(choice).some(variant => visibleForms.has(variant))) {
            addFailure(verb, slot, `visible form used as distractor: ${choice}`);
          }
        });
        if (!checkVerbMemoryAnswer(verb?.[slot], challenge)) {
          addFailure(verb, slot, "checker rejected correct answer");
        }
        challenge.acceptedAnswers.forEach(answer => {
          if (!checkVerbMemoryAnswer(answer, challenge)) {
            addFailure(verb, slot, `checker rejected accepted answer: ${answer}`);
          }
        });
      }
    });
  });

  const report = {
    ok: failures.length === 0,
    totalEntries: IRREGULAR_VERB_MEMORY_BANK.length,
    checkedCases,
    skippedCases: skippedDetails.length,
    runsPerCase,
    generatedChoiceSets,
    failures,
    warnings: skippedDetails.length
      ? [`${skippedDetails.length} challenge combinations skipped because a visible form reveals the answer`]
      : [],
    skippedDetails
  };
  verbMemoryChoiceValidationCache = report;
  const hostname = String(globalThis.location?.hostname || "");
  if (options.logSummary !== false && (hostname === "localhost" || hostname === "127.0.0.1" || !hostname)) {
    console.info("[Verb Memory Practice] choice generation validation:", {
      ok: report.ok,
      totalEntries: report.totalEntries,
      checkedCases: report.checkedCases,
      skippedCases: report.skippedCases,
      generatedChoiceSets: report.generatedChoiceSets,
      failures: report.failures
    });
  }
  return report;
}

function getVerbMemoryPracticeOwnerId() {
  const user = getCurrentUser();
  return String(user?.uid || user?.userId || user?.id || playerData?.userId || "guest");
}

function getVerbMemoryPracticeLocalStorageKey() {
  return `lingua:verbMemoryPracticeBest:${getVerbMemoryPracticeOwnerId()}`;
}

function normalizeVerbMemoryBestRecord(record = {}) {
  return {
    bestScore: Math.max(0, Number(record?.bestScore) || 0),
    bestAccuracy: clamp(Math.max(0, Number(record?.bestAccuracy) || 0), 0, 100),
    bestStreak: Math.max(0, Number(record?.bestStreak) || 0),
    bestCorrect: Math.max(0, Number(record?.bestCorrect) || 0),
    bestTotal: Math.max(0, Number(record?.bestTotal) || 0),
    attempts: Math.max(0, Number(record?.attempts) || 0),
    updatedAt: record?.updatedAt || null
  };
}

function shouldUseFirestoreForVerbMemoryPractice() {
  const user = getCurrentUser();
  const ownerId = getVerbMemoryPracticeOwnerId();
  return Boolean(
    getAuthMode() === "firebase" &&
    !user?.isGuest &&
    ownerId !== "guest" &&
    firebaseAuth?.currentUser?.uid === ownerId
  );
}

async function loadVerbMemoryPracticeBestScore({ force = false } = {}) {
  const ownerId = getVerbMemoryPracticeOwnerId();
  if (!force && verbMemoryPracticeState.bestRecord && verbMemoryPracticeState.bestRecordOwnerId === ownerId) {
    return verbMemoryPracticeState.bestRecord;
  }
  let record = {};
  try {
    if (shouldUseFirestoreForVerbMemoryPractice()) {
      const snapshot = await getDoc(getPlayerDocRef(ownerId));
      record = snapshot.exists() ? snapshot.data()?.verbMemoryPracticeBest || {} : {};
    } else {
      const saved = playerStorage.get(getVerbMemoryPracticeLocalStorageKey());
      record = saved ? JSON.parse(saved) : {};
    }
  } catch (error) {
    console.warn("[Verb Memory Practice] failed to load best score", error);
    record = {};
  }
  verbMemoryPracticeState.bestRecord = normalizeVerbMemoryBestRecord(record);
  verbMemoryPracticeState.bestRecordOwnerId = ownerId;
  return verbMemoryPracticeState.bestRecord;
}

function createVerbMemoryBestRecord(previousRecord, result) {
  const previous = normalizeVerbMemoryBestRecord(previousRecord);
  const accuracy = result.total > 0 ? Math.round((result.correct / result.total) * 100) : 0;
  const useAccuracyResult = accuracy > previous.bestAccuracy ||
    (accuracy === previous.bestAccuracy && result.total > previous.bestTotal);
  return {
    bestScore: Math.max(previous.bestScore, result.score),
    bestAccuracy: useAccuracyResult ? accuracy : previous.bestAccuracy,
    bestStreak: Math.max(previous.bestStreak, result.bestStreak),
    bestCorrect: useAccuracyResult ? result.correct : previous.bestCorrect,
    bestTotal: useAccuracyResult ? result.total : previous.bestTotal,
    attempts: previous.attempts + 1,
    updatedAt: createTimestampIso()
  };
}

async function saveVerbMemoryPracticeBestScore(result) {
  const ownerId = getVerbMemoryPracticeOwnerId();
  let previousRecord = normalizeVerbMemoryBestRecord(verbMemoryPracticeState.bestRecord);
  let nextRecord = createVerbMemoryBestRecord(previousRecord, result);
  if (shouldUseFirestoreForVerbMemoryPractice()) {
    const playerRef = getPlayerDocRef(ownerId);
    await runTransaction(firestoreDb, async transaction => {
      const snapshot = await transaction.get(playerRef);
      if (!snapshot.exists()) {
        throw new Error("Player document not found");
      }
      previousRecord = normalizeVerbMemoryBestRecord(snapshot.data()?.verbMemoryPracticeBest || previousRecord);
      nextRecord = createVerbMemoryBestRecord(previousRecord, result);
      transaction.update(playerRef, {
        verbMemoryPracticeBest: {
          ...nextRecord,
          updatedAt: serverTimestamp()
        }
      });
    });
  } else {
    playerStorage.set(getVerbMemoryPracticeLocalStorageKey(), JSON.stringify(nextRecord));
  }
  verbMemoryPracticeState.bestRecord = nextRecord;
  verbMemoryPracticeState.bestRecordOwnerId = ownerId;
  return {
    record: nextRecord,
    previousBest: previousRecord.bestScore,
    isNewBest: result.score > previousRecord.bestScore
  };
}

function clearVerbMemoryNextRoundTimer() {
  if (verbMemoryPracticeState.nextRoundTimer) {
    clearTimeout(verbMemoryPracticeState.nextRoundTimer);
    verbMemoryPracticeState.nextRoundTimer = null;
  }
}

function resetVerbMemoryPracticeState({ preserveBest = true } = {}) {
  clearVerbMemoryNextRoundTimer();
  const bestRecord = preserveBest ? verbMemoryPracticeState.bestRecord : null;
  const bestRecordOwnerId = preserveBest ? verbMemoryPracticeState.bestRecordOwnerId : "";
  const validation = verbMemoryPracticeState.validation;
  Object.assign(verbMemoryPracticeState, {
    active: false,
    bossId: VERB_MEMORY_CONFIG.bossId,
    bossName: VERB_MEMORY_CONFIG.bossName,
    bossThaiName: VERB_MEMORY_CONFIG.bossThaiName,
    playerHp: VERB_MEMORY_CONFIG.playerMaxHp,
    playerMaxHp: VERB_MEMORY_CONFIG.playerMaxHp,
    bossHp: VERB_MEMORY_CONFIG.bossMaxHp,
    bossMaxHp: VERB_MEMORY_CONFIG.bossMaxHp,
    score: 0,
    correct: 0,
    wrong: 0,
    total: 0,
    streak: 0,
    bestStreak: 0,
    currentChallenge: null,
    usedVerbIds: new Set(),
    startedAt: null,
    endedAt: null,
    isResolving: false,
    nextRoundTimer: null,
    bestRecord,
    bestRecordOwnerId,
    validation,
    lastResult: null
  });
}

function setVerbMemoryStatus(message) {
  if (els.verbMemoryStatusText) {
    els.verbMemoryStatusText.textContent = message;
  }
}

function renderVerbMemoryHpAndScore() {
  const playerPercent = clamp((verbMemoryPracticeState.playerHp / verbMemoryPracticeState.playerMaxHp) * 100, 0, 100);
  const bossPercent = clamp((verbMemoryPracticeState.bossHp / verbMemoryPracticeState.bossMaxHp) * 100, 0, 100);
  els.verbMemoryPlayerHpText.textContent = `HP ${verbMemoryPracticeState.playerHp} / ${verbMemoryPracticeState.playerMaxHp}`;
  els.verbMemoryBossHpText.textContent = `HP ${verbMemoryPracticeState.bossHp} / ${verbMemoryPracticeState.bossMaxHp}`;
  els.verbMemoryPlayerHpBar.style.width = `${playerPercent}%`;
  els.verbMemoryBossHpBar.style.width = `${bossPercent}%`;
  els.verbMemoryScoreText.textContent = `คะแนนฝึกจำ ${verbMemoryPracticeState.score}`;
  els.verbMemoryStreakText.textContent = `คอมโบ ${verbMemoryPracticeState.streak}`;
  els.verbMemoryBestScoreText.textContent = `คะแนนสูงสุด ${Math.max(0, Number(verbMemoryPracticeState.bestRecord?.bestScore) || 0)}`;
}

function setVerbMemorySlot(slot, value, isMissing) {
  const element = els[`verbMemorySlot${slot.toUpperCase()}`];
  if (!element) {
    return;
  }
  element.textContent = value;
  element.closest(".verb-memory-slot")?.classList.toggle("verb-memory-slot-missing", isMissing);
}

function renderVerbMemoryChallenge() {
  const challenge = verbMemoryPracticeState.currentChallenge;
  if (!challenge) {
    setVerbMemorySlot("v1", "พร้อม", false);
    setVerbMemorySlot("v2", "เริ่ม", false);
    setVerbMemorySlot("v3", "ฝึก", false);
    els.verbMemoryChoices.textContent = "";
    return;
  }
  VERB_MEMORY_SLOTS.forEach(slot => {
    const isMissing = slot === challenge.missingSlot;
    setVerbMemorySlot(slot, isMissing ? "???" : challenge[slot], isMissing);
  });
  els.verbMemoryChoices.textContent = "";
  challenge.choices.forEach(choice => {
    const button = document.createElement("button");
    button.type = "button";
    button.className = "verb-memory-choice-button";
    button.textContent = choice;
    button.disabled = verbMemoryPracticeState.isResolving;
    button.addEventListener("click", () => handleVerbMemoryChoice(choice));
    els.verbMemoryChoices.appendChild(button);
  });
}

function renderVerbMemoryPracticeScene() {
  renderVerbMemoryHpAndScore();
  renderVerbMemoryChallenge();
  els.verbMemoryBossName.textContent = verbMemoryPracticeState.bossName;
  els.verbMemoryBossThaiName.textContent = verbMemoryPracticeState.bossThaiName;
  els.verbMemoryPracticeStartButton.classList.toggle("hidden", verbMemoryPracticeState.active || Boolean(verbMemoryPracticeState.lastResult));
  els.verbMemoryResultPanel.classList.toggle("hidden", !verbMemoryPracticeState.lastResult);
}

function applyVerbMemoryBossImage() {
  const image = els.verbMemoryBossSprite;
  const placeholder = els.verbMemoryBossFallback;
  if (!image) {
    placeholder?.classList.remove("hidden");
    return "";
  }
  const primaryPath = getGameAssetUrl(VERB_MEMORY_CONFIG.bossAssetKey, VERB_MEMORY_CONFIG.bossFallbackAsset);
  const safeFallbackPath = VERB_MEMORY_CONFIG.bossSafeFallbackAsset;
  let safeFallbackApplied = false;
  image.dataset.assetKey = VERB_MEMORY_CONFIG.bossAssetKey;
  image.alt = verbMemoryPracticeState.bossName;
  image.classList.remove("hidden");
  placeholder?.classList.add("hidden");
  image.onerror = () => {
    if (!safeFallbackApplied && safeFallbackPath && image.getAttribute("src") !== safeFallbackPath) {
      safeFallbackApplied = true;
      image.src = safeFallbackPath;
      return;
    }
    image.onerror = null;
    image.removeAttribute("src");
    image.classList.add("hidden");
    placeholder?.classList.remove("hidden");
  };
  if (primaryPath) {
    image.src = primaryPath;
  } else if (safeFallbackPath) {
    safeFallbackApplied = true;
    image.src = safeFallbackPath;
  } else {
    image.onerror();
  }
  return image.getAttribute("src") || "";
}

function animateVerbMemoryHit(element, className) {
  if (!element) {
    return;
  }
  element.classList.remove(className);
  void element.offsetWidth;
  element.classList.add(className);
  setTimeout(() => element.classList.remove(className), 380);
}

function queueNextVerbMemoryChallenge() {
  if (!verbMemoryPracticeState.active) {
    return;
  }
  const challenge = generateVerbMemoryChallenge();
  if (!challenge) {
    setVerbMemoryStatus("ไม่สามารถสร้างโจทย์จากคลังคำกริยาได้");
    void finishVerbMemoryPracticeGame("content-error");
    return;
  }
  verbMemoryPracticeState.currentChallenge = challenge;
  verbMemoryPracticeState.isResolving = false;
  renderVerbMemoryChallenge();
  setVerbMemoryStatus(`คำที่ ${challenge.no}: เลือก ${challenge.missingSlot.toUpperCase()} ที่หายไป`);
}

function resolveVerbMemoryCorrect(challenge) {
  verbMemoryPracticeState.correct += 1;
  verbMemoryPracticeState.streak += 1;
  verbMemoryPracticeState.bestStreak = Math.max(verbMemoryPracticeState.bestStreak, verbMemoryPracticeState.streak);
  const damage = verbMemoryPracticeState.streak >= 5
    ? VERB_MEMORY_CONFIG.correctDamageStreak5
    : verbMemoryPracticeState.streak >= 3
      ? VERB_MEMORY_CONFIG.correctDamageStreak3
      : VERB_MEMORY_CONFIG.correctDamageBase;
  const streakBonus = verbMemoryPracticeState.streak >= 5 ? 10 : verbMemoryPracticeState.streak >= 3 ? 5 : 0;
  const points = (VERB_MEMORY_SCORE_BY_SLOT[challenge.missingSlot] || 0) + streakBonus;
  verbMemoryPracticeState.bossHp = clamp(verbMemoryPracticeState.bossHp - damage, 0, verbMemoryPracticeState.bossMaxHp);
  verbMemoryPracticeState.score += points;
  animateVerbMemoryHit(els.verbMemoryBossFrame, "is-hit");
  return `ถูกต้อง! ${challenge.v1} - ${challenge.v2} - ${challenge.v3} แปลว่า “${challenge.meaningTh}”`;
}

function resolveVerbMemoryWrong(challenge) {
  verbMemoryPracticeState.wrong += 1;
  verbMemoryPracticeState.streak = 0;
  verbMemoryPracticeState.playerHp = clamp(
    verbMemoryPracticeState.playerHp - VERB_MEMORY_CONFIG.wrongDamage,
    0,
    verbMemoryPracticeState.playerMaxHp
  );
  animateVerbMemoryHit(els.verbMemoryPlayerHpText?.closest(".verb-memory-player-panel"), "is-hit");
  return `ยังไม่ถูก คำตอบที่ถูกคือ ${challenge.correctAnswer} ชุดกริยาคือ ${challenge.v1} - ${challenge.v2} - ${challenge.v3} แปลว่า “${challenge.meaningTh}”`;
}

function handleVerbMemoryChoice(selectedAnswer) {
  const challenge = verbMemoryPracticeState.currentChallenge;
  if (!verbMemoryPracticeState.active || verbMemoryPracticeState.isResolving || !challenge) {
    return;
  }
  verbMemoryPracticeState.isResolving = true;
  verbMemoryPracticeState.total += 1;
  const isCorrect = checkVerbMemoryAnswer(selectedAnswer, challenge);
  const feedback = isCorrect
    ? resolveVerbMemoryCorrect(challenge)
    : resolveVerbMemoryWrong(challenge);
  els.verbMemoryChoices.querySelectorAll("button").forEach(button => {
    button.disabled = true;
    const isSelected = normalizeVerbMemoryAnswer(button.textContent) === normalizeVerbMemoryAnswer(selectedAnswer);
    const isCorrectChoice = checkVerbMemoryAnswer(button.textContent, challenge);
    button.classList.toggle("is-correct", isCorrectChoice);
    button.classList.toggle("is-wrong", isSelected && !isCorrectChoice);
  });
  renderVerbMemoryHpAndScore();
  setVerbMemoryStatus(feedback);
  const gameEnded = verbMemoryPracticeState.bossHp <= 0 || verbMemoryPracticeState.playerHp <= 0;
  clearVerbMemoryNextRoundTimer();
  verbMemoryPracticeState.nextRoundTimer = setTimeout(() => {
    verbMemoryPracticeState.nextRoundTimer = null;
    if (gameEnded) {
      void finishVerbMemoryPracticeGame(verbMemoryPracticeState.bossHp <= 0 ? "boss-defeated" : "player-defeated");
      return;
    }
    queueNextVerbMemoryChallenge();
  }, VERB_MEMORY_CONFIG.nextRoundDelayMs);
}

function renderVerbMemoryResult(result, { isNewBest = false, saveWarning = "" } = {}) {
  const bestScore = Math.max(result.score, Number(verbMemoryPracticeState.bestRecord?.bestScore) || 0);
  els.verbMemoryResultTitle.textContent = result.reason === "boss-defeated"
    ? "เจ้าชนะ The Memory Breaker!"
    : result.reason === "player-defeated"
      ? "The Memory Breaker ทำลายความทรงจำของเจ้าแล้ว"
      : "การฝึกฝนจบลง";
  els.verbMemoryResultScore.textContent = String(result.score);
  els.verbMemoryResultAccuracy.textContent = `${result.correct} / ${result.total} (${result.accuracy}%)`;
  els.verbMemoryResultBestStreak.textContent = String(result.bestStreak);
  els.verbMemoryResultBestScore.textContent = String(bestScore);
  els.verbMemoryResultRecord.textContent = [isNewBest ? "สถิติใหม่!" : "", saveWarning].filter(Boolean).join(" ");
  els.verbMemoryResultPanel.classList.remove("hidden");
  els.verbMemoryPracticeStartButton.classList.add("hidden");
  renderVerbMemoryHpAndScore();
}

async function finishVerbMemoryPracticeGame(reason) {
  if (!verbMemoryPracticeState.active) {
    return;
  }
  clearVerbMemoryNextRoundTimer();
  verbMemoryPracticeState.active = false;
  verbMemoryPracticeState.isResolving = true;
  verbMemoryPracticeState.endedAt = Date.now();
  const accuracy = verbMemoryPracticeState.total > 0
    ? Math.round((verbMemoryPracticeState.correct / verbMemoryPracticeState.total) * 100)
    : 0;
  const result = {
    reason,
    score: verbMemoryPracticeState.score,
    correct: verbMemoryPracticeState.correct,
    wrong: verbMemoryPracticeState.wrong,
    total: verbMemoryPracticeState.total,
    accuracy,
    bestStreak: verbMemoryPracticeState.bestStreak,
    startedAt: verbMemoryPracticeState.startedAt,
    endedAt: verbMemoryPracticeState.endedAt
  };
  const previousBest = Math.max(0, Number(verbMemoryPracticeState.bestRecord?.bestScore) || 0);
  const provisionalRecord = createVerbMemoryBestRecord(verbMemoryPracticeState.bestRecord, result);
  verbMemoryPracticeState.lastResult = result;
  renderVerbMemoryResult(result, { isNewBest: result.score > previousBest });
  try {
    const saved = await saveVerbMemoryPracticeBestScore(result);
    renderVerbMemoryResult(result, { isNewBest: saved.isNewBest });
  } catch (error) {
    console.error("[Verb Memory Practice] failed to save best score", error);
    verbMemoryPracticeState.bestRecord = provisionalRecord;
    renderVerbMemoryResult(result, {
      isNewBest: result.score > previousBest,
      saveWarning: "บันทึกคะแนนสูงสุดไม่ได้ แต่ผลรอบนี้ยังแสดงอยู่"
    });
  }
}

function startVerbMemoryPracticeGame() {
  if (verbMemoryPracticeState.active) {
    return;
  }
  if (!verbMemoryPracticeState.validation?.ok) {
    setVerbMemoryStatus("คลังคำกริยายังไม่พร้อม จึงไม่สามารถเริ่มการฝึกได้");
    return;
  }
  resetVerbMemoryPracticeState({ preserveBest: true });
  verbMemoryPracticeState.active = true;
  verbMemoryPracticeState.startedAt = Date.now();
  els.verbMemoryResultPanel.classList.add("hidden");
  els.verbMemoryPracticeStartButton.classList.add("hidden");
  renderVerbMemoryHpAndScore();
  queueNextVerbMemoryChallenge();
}

async function openVerbMemoryPracticeScene() {
  closeGameModal();
  const ownerId = getVerbMemoryPracticeOwnerId();
  if (verbMemoryPracticeState.bestRecordOwnerId !== ownerId) {
    verbMemoryPracticeState.bestRecord = null;
    verbMemoryPracticeState.bestRecordOwnerId = "";
  }
  resetVerbMemoryPracticeState({ preserveBest: true });
  const bankValidation = validateIrregularVerbMemoryBank();
  const choiceValidation = bankValidation.ok
    ? validateVerbMemoryChoiceGeneration()
    : {
      ok: false,
      totalEntries: bankValidation.count,
      checkedCases: 0,
      skippedCases: 0,
      failures: ["Choice validation skipped because the verb bank is invalid"],
      warnings: []
    };
  verbMemoryPracticeState.validation = {
    ok: bankValidation.ok && choiceValidation.ok,
    count: bankValidation.count,
    bank: bankValidation,
    choices: choiceValidation,
    failures: [...bankValidation.failures, ...choiceValidation.failures]
  };
  applyVerbMemoryBossImage();
  renderVerbMemoryPracticeScene();
  setVerbMemoryStatus(verbMemoryPracticeState.validation.ok
    ? `คลังคำกริยาพร้อม ${verbMemoryPracticeState.validation.count} คำ ตรวจแล้ว ${choiceValidation.checkedCases} รูปแบบ ข้าม ${choiceValidation.skippedCases} รูปแบบที่คำตอบถูกเปิดเผย กำลังเริ่มต่อสู้กับ The Memory Breaker`
    : "ตรวจพบปัญหาในคลังคำกริยา จึงยังไม่เปิดการฝึก");
  els.verbMemoryPracticeStartButton.disabled = !verbMemoryPracticeState.validation.ok;
  showScene("verbMemoryPractice");
  if (verbMemoryPracticeState.validation.ok) {
    startVerbMemoryPracticeGame();
  }
  await loadVerbMemoryPracticeBestScore();
  renderVerbMemoryHpAndScore();
}

function returnFromVerbMemoryPracticeToMainMenu() {
  clearVerbMemoryNextRoundTimer();
  verbMemoryPracticeState.active = false;
  verbMemoryPracticeState.isResolving = false;
  verbMemoryPracticeState.currentChallenge = null;
  renderMainMenu();
  showScene("mainMenu");
}

function startPracticeLessonFromMap(stage, stageIndex, source = "lesson-map-code") {
  if (!stage || stageIndex < 0 || state.isTransitioning) {
    return;
  }
  beginPracticeMode(stage, source);
  state.practiceUnlockStageIds.add(stage.id);
  state.activeReplayLessonId = null;
  state.replayReturnProgress = null;
  closeGameModal();
  runSceneTransition("กำลังเปิดโหมดฝึก...", () => {
    showStageLesson(stageIndex, { lessonStepIndex: 0, dialogueIndex: 0, isPractice: true });
  });
}

function openPracticeUnlockModal(stage, stageIndex, source = "lesson-map-code") {
  const content = document.createElement("div");
  content.className = "practice-unlock-form";
  const note = document.createElement("p");
  note.textContent = "โหมดฝึกจะไม่ให้ Grammaria, Fragment, Badge หรือความคืบหน้า";
  const input = document.createElement("input");
  input.type = "password";
  input.placeholder = "กรอกรหัส";
  input.autocomplete = "off";
  input.setAttribute("aria-label", "กรอกรหัสสำหรับโหมดฝึก");
  const error = document.createElement("p");
  error.className = "form-status";
  content.append(note, input, error);

  const verifyAndStart = () => {
    if (input.value.toLowerCase().trim() !== PRACTICE_UNLOCK_CODE) {
      error.textContent = "รหัสไม่ถูกต้อง กรุณาตรวจสอบอีกครั้ง";
      els.gameModal.dataset.modalLocked = "false";
      els.gameModalActions.querySelectorAll("button").forEach(button => setButtonEnabled(button, true));
      setButtonEnabled(els.gameModalClose, true);
      input.focus();
      input.select();
      return;
    }
    startPracticeLessonFromMap(stage, stageIndex, source);
  };

  input.addEventListener("keydown", event => {
    if (event.key === "Enter") {
      event.preventDefault();
      verifyAndStart();
    }
  });
  openGameModal({
    title: "ปลดล็อกบทเรียนสำหรับฝึก",
    body: "บทเรียนนี้ยังไม่ปลดล็อกในเส้นทางหลัก หากต้องการฝึกบทนี้ ให้กรอกรหัสจากครู",
    content,
    actions: [
      { label: "ยกเลิก", onClick: closeGameModal },
      { label: "ปลดล็อกเพื่อฝึก", primary: true, onClick: verifyAndStart }
    ]
  });
  requestAnimationFrame(() => input.focus());
}

function confirmReplayLesson(stage, stageIndex) {
  openGameModal({
    title: "เรียนซ้ำบทเรียน",
    body: "คุณต้องการเรียนซ้ำบทเรียนนี้หรือไม่? การเรียนซ้ำจะไม่ได้รับ Grammaria หรือรางวัลซ้ำ",
    actions: [
      { label: "ยกเลิก", onClick: closeGameModal },
      {
        label: "เรียนซ้ำ",
        primary: true,
        onClick: () => startLessonFromLessonMap(stage, stageIndex, { isReplay: true })
      }
    ]
  });
}

function handleLessonReviewEntryClick(entry, button) {
  if (!entry || state.isTransitioning || button?.dataset.reviewLocked === "true") {
    return;
  }
  if (button) {
    button.dataset.reviewLocked = "true";
    setButtonEnabled(button, false);
  }
  if (entry.shouldReplay) {
    confirmReplayLesson(entry.stage, entry.stageIndex);
    return;
  }
  startLessonFromLessonMap(entry.stage, entry.stageIndex);
}

function openLessonProgressReviewModal(event = null) {
  if (event) {
    event.preventDefault();
    event.stopPropagation();
  }
  if (!scenes.story?.classList.contains("active") || state.isTransitioning) {
    return;
  }

  const progress = loadProgress();
  const entries = buildReachedLessonReviewEntries(progress);
  const content = document.createElement("div");
  content.className = "lesson-select-grid lesson-progress-review-grid";

  if (!entries.length) {
    const empty = document.createElement("p");
    empty.className = "lesson-progress-review-empty";
    empty.textContent = "ยังไม่พบบทเรียนที่เปิดให้ทบทวน";
    content.appendChild(empty);
  }

  entries.forEach(entry => {
    const button = document.createElement("button");
    button.type = "button";
    button.className = `lesson-select-card lesson-review-card ${entry.isCompleted ? "is-completed" : ""} ${entry.isCurrent ? "is-current" : ""}`;
    button.innerHTML = `
      <strong>บทเรียน ${entry.number}</strong>
      <span>${entry.stage.title || "Untitled Lesson"}</span>
      <span>${entry.stage.thaiTitle || entry.stage.title || "บทเรียน"}</span>
      <em>สถานะ: ${entry.status}${entry.shouldReplay ? " / เรียนซ้ำได้" : " / เล่นต่อ"}</em>
    `;
    button.addEventListener("click", () => handleLessonReviewEntryClick(entry, button));
    content.appendChild(button);
  });

  openGameModal({
    title: "เลือกบทเรียนที่เคยเรียนแล้ว",
    body: "เลือกบทเรียนเพื่อทบทวนเนื้อหา บทเรียนอนาคตจะไม่แสดงในรายการนี้",
    content,
    actions: [{ label: "ปิด", onClick: closeGameModal }]
  });
}

function handleLessonProgressBadgeKeydown(event) {
  if (event.key === "Enter" || event.key === " ") {
    openLessonProgressReviewModal(event);
  }
}

